        const path = op[1].slice(1);
        switch (op[0]) {
            case "p":
                result.push(["p", path, op[2], op[3], op[4]]);
                break;
            case "m":
                result.push(["m", path, op[2]]);
                break;
            default:
                // s/d/a/t on the value itself replace it.
                if (path.length === 0)
                    return [["r", value]];
                if (op[0] === "d")
