        }
        if (close)
            this.link.close(`protocol-version ${PROTOCOL_VERSION}`);
    }

#violation(reason) {
        this.host.report(new ChordError("invalid", `link to ${this.name ?? "peer"}: ${reason}`, { reason: "protocol" }));
        this.link.close(`protocol error: ${reason}`);
    }

hold(binding, again) {
        const id = this.nextId();
        this.remotes.set(id, binding);
        binding.bound(this, id);
        const principal = binding.principal;
        this.send({
            t: "hold",
            id,
            at: binding.at,
            token: binding.contract.description,
            input: binding.input,
            ...(principal === undefined ? {} : { principal }),
            ...(binding.stateOn ? {} : { state: false }),
            ...(again ? { again: true } : {}),
        });
        return id;
    }

release(id) {
        this.remotes.delete(id);
        this.send({ t: "release", id });
    }

wantState(hold, wanted) {
        if (this.remotes.has(hold))
            this.send({ t: wanted ? "sub" : "unsub", hold });
    }

call(hold, member, args, root, signal) {
        const id = this.nextId();
        return new Promise((resolve, reject) => {
            if (signal.aborted) {
                reject(new ChordError("aborted", "call aborted"));
                return;
            }
            const onAbort = () => {
                this.calls.delete(id);
                this.send({ t: "cancel", id });
                reject(new ChordError("aborted", "call aborted", { cause: signal.reason }));
            };
            signal.addEventListener("abort", onAbort, { once: true });
            const done = () => signal.removeEventListener("abort", onAbort);
            this.calls.set(id, {
                resolve: (value) => {
                    done();
                    resolve(value);
                },
                reject: (error) => {
                    done();
                    reject(error);
                },
            });
            // Clients never carry roots or code versions: the server starts roots for them.
            const carried = root !== undefined && this.host.kind === "host";
            if (carried)
                this.host.rootSent(root.rootId, this);
            this.send({ t: "call", id, hold, member, args, ...(carried ? { root } : {}) });
        });
    }

#receive(frame) {
        if (this.#mismatched)
            return;
        this.#lastSeen = Date.now();
        if (!isFrame(frame)) {
            this.#violation("malformed frame");
            return;
        }
        if (frame.t === "ack") {
            this.#onAck(frame.n);
            return;
        }
        this.#received++;
        try {
            this.#dispatch(frame);
        }
        catch (error) {
            this.host.report(error);
        }
        this.#scheduleAck();
    }

#dispatch(frame) {
        switch (frame.t) {
            case "hello":
                this.#onHello(frame);
                return;
            case "ping":
                this.send({ t: "pong", n: frame.n });
                return;
            case "pong":
            case "bye":
            case "ack":
                return;
            case "hold":
                this.#onHold(frame);
                return;
            case "release":
                this.#dropServed(frame.id, true);
                return;
            case "call":
                this.#onCall(frame);
                return;
            case "cancel":
                this.incoming.get(frame.id)?.abort(new ChordError("aborted", "cancelled by caller"));
                return;
            case "sub":
            case "unsub":
                this.#onWantState(frame.hold, frame.t === "sub");
                return;
            case "resync":
                this.#onResync(frame.hold, frame.m);
                return;
            case "shape":
            case "gone":
                this.#onHoldReply(frame);
                return;
            case "result":
                this.#onResult(frame);
                return;
            case "state":
                this.#onState(frame);
                return;
            case "root_end":
                // Honored only from the link the root came over (see HostImpl.foreignRootEnded).
                this.#admitted.delete(frame.rootId);
                this.host.foreignRootEnded(frame.rootId, this);
                return;
            case "invalidate":
            case "prepare":
            case "commit":
            case "abort":
            case "retire":
                // Control frames only from the parent.
                if (this.role !== "upstream") {
                    this.#violation(`${frame.t} from a child`);
                    return;
                }
                if (frame.t === "invalidate") {
                    this.host.invalidatePrincipal(frame.pattern).catch((error) => this.host.report(error));
                }
                else if (frame.t === "retire")
                    this.host.allowRetire(frame.codeVersion);
                else
                    this.host.onReloadFrame(this, frame);
                return;
            case "vote": {
                if (this.role !== "downstream" || this.peer.kind !== "host") {
                    this.#violation("vote from a non-participant");
                    return;
                }
                const vote = this.votes.get(frame.reload);
                this.votes.delete(frame.reload);
                if (frame.error === undefined)
                    vote?.resolve(frame.report);
                else
                    vote?.reject(fromWireError(frame.error));
                return;
            }
        }
    }

#onHello(frame) {
        if ((frame.protocol ?? 1) !== PROTOCOL_VERSION) {
            this.#protocolMismatch(frame.protocol ?? 1);
            return;
        }
        if (this.#peerAcks === undefined) {
            this.#peerAcks = frame.acks === true;
            if (!this.#peerAcks) {
                this.#unacked = [];
                this.#unackedBytes = 0;
            }
        }
        if (this.role === "upstream") {
            if (frame.kind !== "host") {
                this.#violation("parent is not a host");
                return;
            }
            this.#parentName ??= frame.name;
            return;
        }
        if (frame.kind !== this.peer.kind || (this.peer.name !== undefined && frame.name !== this.peer.name)) {
            this.#violation(`hello ${frame.kind} ${frame.name} does not match the accepted ${this.peer.kind} ${this.peer.name ?? ""}`);
            return;
        }
        if (this.peer.kind === "host")
            this.host.peerHello(this, frame.codeVersion);
    }

#principalOf(frame) {
        if (this.role === "downstream")
            return this.principal;
        return frame.principal ?? this.principal;
    }

#originOf(frame) {
        return this.role === "downstream" ? this.originId : frame.origin;
    }

#onHold(frame) {
        if (this.served.has(frame.id)) {
            this.#violation(`duplicate hold id ${frame.id}`);
            return;
        }
        const principal = this.#principalOf(frame);
        const origin = this.#originOf(frame);
        const client = origin !== undefined;
        if (frame.at !== this.host.name) {
            if (this.role === "upstream") {
                this.send({ t: "gone", id: frame.id, error: toWireError(unavailable(`${this.host.name} does not relay`)) });
                return;
            }
            const relay = new RelayRef(this, frame, principal, origin);
            this.served.set(frame.id, { kind: "relay", relay });
            this.host.relay(relay).catch((error) => relay.close(error, { releaseDown: true, notify: true }));
            return;
        }
        let ref;
        try {
            const token = contractFromDescription(frame.token);
            if (token.scope !== "remote")
                throw invalid("token", `${token.name} is local; only remote types cross links`);
            // Addressed here, so the input must place it here (also by this host's contract, checked when acquiring).
            if (resolveHost(token.name, token.description.host, frame.input) !== this.host.name)
                throw invalid("placement", `${token.name} with this input does not live on ${this.host.name}`);
            const acquired = this.host.acquire(token, frame.input, { principal }, client ? "client" : "connection");
            if (!(acquired instanceof RefImpl))
                throw unavailable("not a local reference");
            ref = acquired;
        }
        catch (error) {
            this.send({ t: "gone", id: frame.id, error: toWireError(client ? clientError(error) : error) });
            return;
        }
        const served = {
            kind: "local",
            id: frame.id,
            ref,
            principal,
            origin,
            wantsState: frame.state !== false,
            again: frame.again === true,
            unitSent: false,
            feeds: new Map(),
        };
        this.served.set(frame.id, served);
        ref.onShape(() => this.#unit(served));
        ref.goneListeners.add((error) => {
            if (this.served.get(frame.id) !== served)
                return;
            this.#dropServed(frame.id, false);
            this.send({ t: "gone", id: frame.id, error: toWireError(error) });
        });
        if (ref.status === "live")
            this.#unit(served);
    }

#stateMembers(ref, shape) {
        return shape.members.filter((name) => ref.describe(shape.variant, name)?.kind === "state");
    }

#unit(served) {
        if (this.served.get(served.id) !== served)
            return;
        const shape = served.ref.shape;
        if (shape === undefined)
            return;
        const members = new Set(served.wantsState ? this.#stateMembers(served.ref, shape) : []);
        for (const [name, feed] of served.feeds) {
            if (members.has(name))
                continue;
            feed.unsubscribe();
            served.feeds.delete(name);
            this.dropState(served.id, name);
        }
        const urgent = served.feeds.size === 0 && !(served.again && !served.unitSent);
        if (urgent)
            this.#sendUnit(served);
        else
            this.#queueUnit(served.id, () => this.#sendUnit(served));
    }

#sendUnit(served) {
        this.#pending.delete(unitKey(served.id));
        if (this.served.get(served.id) !== served)
            return;
        const shape = served.ref.shape;
        if (shape === undefined)
            return;
        served.unitSent = true;
        const members = served.wantsState ? this.#stateMembers(served.ref, shape) : [];
        const listed = members.filter((name) => !served.feeds.has(name));
        const snaps = [];
        const attached = [];
        for (const name of listed) {
            const attachment = this.#attach(served, name);
            if (attachment === undefined)
                continue;
            snaps.push(attachment.frame);
            attached.push([name, attachment.feed]);
        }
        this.send({
            t: "shape",
            id: served.id,
            ...(shape.variant === undefined ? {} : { variant: shape.variant }),
            members: shape.members,
            contract: shape.contract,
            state: snaps.map((frame) => frame.m),
        });
        for (const frame of snaps)
            this.send(frame);
        for (const [name, feed] of attached)
            this.#replay(served, name, feed);
    }

#attach(served, name, as = "snap") {
        const readable = served.ref.member(name);
        if (readable === undefined || typeof readable.events !== "function")
            return undefined;
        const feed = { unsubscribe: () => { }, encoder: encoder(), buffer: [] };
        let first;
        feed.unsubscribe = readable.events((event) => {
            if (first === undefined)
                first = event;
            else if (feed.buffer !== undefined)
                feed.buffer.push(event);
            else
                this.#feedEvent(served, name, feed, event);
        });
        served.feeds.set(name, feed);
        return { frame: this.#snapshot(served, name, as, first?.value), feed };
    }

#replay(served, name, feed) {
        const buffered = feed.buffer ?? [];
        feed.buffer = undefined;
        for (const event of buffered)
            this.#feedEvent(served, name, feed, event);
    }

#snapshot(served, name, as, value) {
        try {
            validateSnapshot(served.ref, name, value);
        }
        catch (error) {
            return { t: "state", hold: served.id, m: name, as: "error", error: toWireError(error) };
        }
        return { t: "state", hold: served.id, m: name, as, ...(value === undefined ? {} : { value }) };
    }

#feedEvent(served, name, feed, event) {
        if (served.feeds.get(name) !== feed)
            return;
        const overflow = { resend: () => this.#resend(served, name) };
        if (event.type === "ops") {
            this.sendState({ t: "state", hold: served.id, m: name, as: "ops", ops: feed.encoder.encode(event.ops) }, overflow);
            return;
        }
        feed.encoder = encoder();
        this.sendState(this.#snapshot(served, name, "reset", event.value), overflow);
    }

#resend(served, name) {
        const feed = served.feeds.get(name);
        if (feed === undefined || this.served.get(served.id) !== served)
            return;
        feed.unsubscribe();
        served.feeds.delete(name);
        const attachment = this.#attach(served, name, "reset");
        if (attachment === undefined)
            return;
        this.send(attachment.frame);
        this.#replay(served, name, attachment.feed);
    }

#onWantState(hold, wanted) {
        const served = this.served.get(hold);
        if (served === undefined)
            return;
        if (served.kind === "relay") {
            served.relay.wantState(wanted);
            return;
        }
        if (served.wantsState === wanted)
            return;
        served.wantsState = wanted;
        if (wanted) {
            this.#unit(served);
            return;
        }
        for (const feed of served.feeds.values())
            feed.unsubscribe();
        served.feeds.clear();
        this.dropHoldState(hold);
    }

#onResync(hold, m) {
        const served = this.served.get(hold);
        if (served === undefined)
            return;
        if (served.kind === "relay") {
            served.relay.resync(m);
            return;
        }
        if (!served.feeds.has(m))
            return;
        this.#resetLater(hold, m, () => this.#resend(served, m));
    }

#dropServed(id, release) {
        const served = this.served.get(id);
        if (served === undefined)
            return;
        this.served.delete(id);
        if (served.kind === "relay") {
            served.relay.close(new ChordError("released", "relayed hold released"), {
                releaseDown: release,
                notify: false,
            });
            return;
        }
        for (const feed of served.feeds.values())
            feed.unsubscribe();
        served.feeds.clear();
        this.dropHoldState(id);
        if (release)
            served.ref.release();
    }

#onCall(frame) {
        if (this.incoming.has(frame.id)) {
            this.#violation(`duplicate call id ${frame.id}`);
            return;
        }
        if (this.incoming.size >= this.#maxCalls) {
            const error = new ChordError("unavailable", `Too many calls in progress on this connection (${this.#maxCalls}); wait for earlier ones to finish`, { reason: "too_many_calls" });
            this.send({ t: "result", id: frame.id, error: toWireError(error) });
            return;
        }
        const served = this.served.get(frame.hold);
        if (served === undefined) {
            this.send({ t: "result", id: frame.id, error: toWireError(new ChordError("gone", "unknown hold")) });
            return;
        }
        const controller = new AbortController();
        this.incoming.set(frame.id, controller);
        // Roots are honored from hosts only; a request without one (or from a client) starts one here.
        const root = this.peer.kind === "host" ? this.#admitRoot(frame.root) : undefined;
        const principal = served.kind === "local" ? served.principal : served.relay.principal;
        const options = { principal, signal: controller.signal };
        const run = served.kind === "local"
            ? (ctx) => served.ref.object.call(served.ref, frame.member, unpack(frame.args), ctx)
            : (ctx) => relayCall(served.relay, frame, { rootId: ctx.rootId, codeVersion: ctx.codeVersion }, 
            // The root's signal: a cancel from the origin and the root's code version retiring both reach it.
            ctx.signal, this.host);
        const result = root === undefined
            ? this.host.root(run, options)
            : this.host.joinRoot(root.rootId, root.codeVersion, run, { ...options, from: this });
        result
            .then((value) => this.send({ t: "result", id: frame.id, value }), (error) => this.send({ t: "result", id: frame.id, error: toWireError(error) }))
            .finally(() => this.incoming.delete(frame.id));
    }

#admitRoot(root) {
        if (root === undefined || this.role !== "downstream" || !this.fencedCodeVersions.has(root.codeVersion))
            return root;
        if (this.host.hasCodeVersion(root.codeVersion))
            return root;
        let codeVersion = this.#admitted.get(root.rootId);
        if (codeVersion === undefined) {
            codeVersion = this.host.current.id;
            this.#admitted.set(root.rootId, codeVersion);
        }
        return { rootId: root.rootId, codeVersion };
    }

#onHoldReply(frame) {
        const relay = this.relayedRefs.get(frame.id);
        if (relay !== undefined) {
            if (frame.t === "gone")
                relay.close(fromWireError(frame.error), { releaseDown: false, notify: true });
            else
                relay.shape(frame);
            return;
        }
        const binding = this.remotes.get(frame.id);
        if (binding === undefined)
            return;
        if (frame.t === "gone") {
            this.remotes.delete(frame.id);
            binding.gone(fromWireError(frame.error));
            return;
        }
        binding.shaped({ variant: frame.variant, members: frame.members, contract: frame.contract }, frame.state);
    }

#onResult(frame) {
        const relayed = this.relayedCalls.get(frame.id);
        if (relayed !== undefined) {
            relayed.finish(frame.error === undefined ? undefined : fromWireError(frame.error), frame.value);
            return;
        }
        const pending = this.calls.get(frame.id);
        this.calls.delete(frame.id);
        if (frame.error !== undefined) {
            pending?.reject(fromWireError(frame.error));
            return;
        }
        let value;
        try {
            value = unpack(frame.value);
        }
        catch (error) {
            pending?.reject(error);
            return;
        }
        pending?.resolve(value);
    }

#onState(frame) {
        const relay = this.relayedRefs.get(frame.hold);
        if (relay !== undefined) {
            relay.state(frame);
            return;
        }
        const binding = this.remotes.get(frame.hold);
        if (binding === undefined)
            return;
        if (!(frame.value instanceof Packed)) {
            binding.state(frame.m, frame);
            return;
        }
        let value;
        try {
            value = unpack(frame.value);
        }
        catch (error) {
            binding.state(frame.m, { as: "error", error: toWireError(error) });
            return;
        }
        binding.state(frame.m, { ...frame, value });
    }

#closed(reason) {
        const told = /^protocol-version (\d+)$/.exec(reason);
        if (told !== null && Number(told[1]) !== PROTOCOL_VERSION)
            this.#protocolMismatch(Number(told[1]), false);
        if (this.#pinger !== undefined)
            clearInterval(this.#pinger);
        if (this.#ackTimer !== undefined)
            clearTimeout(this.#ackTimer);
        this.#pending.clear();
        this.#pendingBytes = 0;
        const error = unavailable(`link to ${this.name ?? "peer"} closed: ${reason}`);
        // As origin: everything the peer held here, relayed or not, is released (downstream calls cancelled).
        for (const id of [...this.served.keys()])
            this.#dropServed(id, true);
        for (const controller of this.incoming.values())
            controller.abort(error);
        this.incoming.clear();
        for (const pending of this.calls.values())
            pending.reject(error);
        this.calls.clear();
        for (const vote of this.votes.values())
            vote.reject(error);
        this.votes.clear();
        for (const waiter of this.#syncWaiters)
            waiter.reject(error);
        this.#syncWaiters.clear();
        // As downstream of relays: their origins lose the hold.
        for (const relay of [...this.relayedRefs.values()])
            relay.close(error, { releaseDown: false, notify: true });
        this.relayedRefs.clear();
        this.relayedCalls.clear();
        const bindings = [...this.remotes.values()];
        this.remotes.clear();
        for (const binding of bindings) {
            // An upstream link may be replaced (reconnect); a downstream host that went away is gone.
            if (this.role === "upstream")
                binding.detached();
            else
                binding.gone(error);
        }
        this.host.connectionClosed(this);
    }

async function relayCall(relay, frame, root, signal, host) {
    const abortError = () => new ChordError("aborted", "call cancelled", { cause: signal.reason });
    if (signal.aborted)
        throw abortError();
    let onAbort = () => { };
    let onCancel = () => { };
    const aborted = new Promise((_, reject) => {
        onAbort = () => reject(abortError());
        signal.addEventListener("abort", onAbort, { once: true });
    });
    aborted.catch(() => { });
    try {
        const down = await Promise.race([relay.ready(), aborted]);
        if (relay.closed)
            throw new ChordError("gone", "relayed hold closed");
        return await new Promise((resolve, reject) => {
            const call = new RelayCall(relay, frame.id, down.nextId(), { resolve, reject });
            onCancel = () => call.cancel(abortError(), true);
            signal.addEventListener("abort", onCancel, { once: true });
            host.rootSent(root.rootId, down);
            down.send({ t: "call", id: call.downId, hold: relay.downId, member: frame.member, args: frame.args, root });
        });
    }
    finally {
        signal.removeEventListener("abort", onAbort);
        signal.removeEventListener("abort", onCancel);
    }
}

function validateSnapshot(ref, member, value) {
    if (value === undefined)
        return;
    const installed = ref.object.currentInstalled();
    if (installed === undefined)
        return;
    const view = ref.currentView();
    const variant = view === undefined ? variantOf(installed.implementation) : variantOf(view);
    const description = view !== undefined && view !== installed.implementation
        ? ref.contract.description.variants[variant ?? LOCAL_VARIANT]?.[member]
        : installed.service.contract.description.variants[variantOf(installed.implementation) ?? LOCAL_VARIANT]?.[member];
    if (description?.kind === "state")
        assertValid("state", `${ref.address}.${member}`, description.schema, value);
}

function clientError(error) {
    if (error instanceof ChordError && error.code === "contract_mismatch") {
        return new ChordError("upgrade_required", error.message, { cause: error });
    }
    return error;
}

get abortSignal() {
        return this.value(ABORT_SIGNAL_CONTEXT_KEY);
    }

value(_key) {
        return undefined;
    }

toString() {
        return this.#name;
    }

value(key) {
        if (key.token === this.#key.token)
            return this.#value;
        return this.#parent.value(key);
    }

toString() {
        return `${this.#parent}.WithValue(${this.#key.token.description ?? "anonymous"})`;
    }

export function createContextKey(description) {
    return Object.freeze({ token: Symbol(description) });
}

export function withContextValue(key, value, parent) {
    return new ContextValue(parent, key, value);
}

export function withAbortSignal(signal, context) {
    const parentSignal = context.abortSignal;
    const combined = parentSignal === undefined ? signal : AbortSignal.any([parentSignal, signal]);
    return withContextValue(ABORT_SIGNAL_CONTEXT_KEY, combined, context);
}

export function withoutAbortSignal(context) {
    return withContextValue(ABORT_SIGNAL_CONTEXT_KEY, undefined, context);
}

export function withCancel(context) {
    const controller = new AbortController();
    return {
        context: withAbortSignal(controller.signal, context),
        cancel: (reason) => controller.abort(reason),
    };
}

export function awaitWithContext(promise, context) {
    const signal = context.abortSignal;
    if (signal === undefined)
        return promise;
    if (signal.aborted)
        return Promise.reject(abortError(signal));
    return new Promise((resolve, reject) => {
        const onAbort = () => reject(abortError(signal));
        signal.addEventListener("abort", onAbort, { once: true });
        void promise.then((value) => {
            signal.removeEventListener("abort", onAbort);
            resolve(value);
        }, (error) => {
            signal.removeEventListener("abort", onAbort);
            reject(error);
        });
    });
}

function abortError(signal) {
    const reason = signal.reason;
    return reason instanceof Error ? reason : new DOMException("The operation was aborted", "AbortError");
}

export function method(args, result) {
    return { [MEMBER]: "method", args, result };
}

export function hostNamed(name) {
    if (typeof name !== "string" || name === "")
        throw new TypeError("hostNamed needs a host name");
    return { name };
}

export function hostFamily(prefix, key) {
    if (typeof prefix !== "string" || prefix === "")
        throw new TypeError("hostFamily needs a host-name prefix");
    if (typeof key !== "string" || key === "")
        throw new TypeError("hostFamily needs an input field name");
    return { prefix, key };
}

export function resolveHost(typeName, placement, input) {
    if ("name" in placement)
        return placement.name;
    const value = input !== null && typeof input === "object" ? input[placement.key] : undefined;
    if (typeof value !== "string" || value === "")
        throw invalid("placement", `${typeName}: input field ${placement.key} names no host`);
    return placement.prefix + value;
}

function describeMember(name, member, scope) {
    if (RESERVED_MEMBERS.has(name))
        throw new TypeError(`member name is reserved: ${name}`);
    const brand = member[MEMBER];
    if (brand === "method") {
        const spec = member;
        return {
            kind: "method",
            ...(spec.args === undefined ? {} : { args: spec.args }),
            ...(spec.result === undefined ? {} : { result: spec.result }),
        };
    }
    if (brand === "opaque") {
        if (scope === "remote")
            throw new TypeError(`remote contracts cannot expose opaque members: ${name}`);
        return { kind: "opaque", id: member.id };
    }
    return { kind: "state", schema: member };
}

function finish(contract) {
    return { ...contract, fingerprint: hash64(canonicalJson(contract.description)) };
}

function checkHeader(name, version) {
    if (!name)
        throw new TypeError("contract name is empty");
    if (!Number.isInteger(version) || version < 1)
        throw new TypeError(`contract version must be a positive integer`);
}

export function remote(name, def) {
    checkHeader(name, def.version);
    const placement = def.host;
    if (placement === undefined || !Value.Check(PlacementSchema, placement))
        throw new TypeError(`remote contract ${name} needs \`host\`: hostNamed(…) or hostFamily(…)`);
    // A JSON copy: the description travels, and a placement object may carry nothing else.
    const host = "name" in placement ? { name: placement.name } : { prefix: placement.prefix, key: placement.key };
    const variants = {};
    if (Object.keys(def.variants).length === 0)
        throw new TypeError(`remote contract ${name} has no variants`);
    for (const [kind, variant] of Object.entries(def.variants)) {
        const members = {};
        for (const [key, schema] of Object.entries(variant.state ?? {}))
            members[key] = describeMember(key, schema, "remote");
        for (const [key, spec] of Object.entries(variant.methods ?? {})) {
            if (key in members)
                throw new TypeError(`member ${key} is both state and method in ${name}.${kind}`);
            members[key] = describeMember(key, spec, "remote");
            if (members[key].kind !== "method")
                throw new TypeError(`methods.${key} is not a method()`);
        }
        variants[kind] = members;
    }
    const description = { name, scope: "remote", version: def.version, input: def.input, host, variants };
    return finish({
        scope: "remote",
        name,
        version: def.version,
        input: def.input,
        def,
        description,
    });
}

export function local(name, def) {
    checkHeader(name, def.version);
    const members = {};
    for (const [key, member] of Object.entries(def.members ?? {}))
        members[key] = describeMember(key, member, "local");
    const description = {
        name,
        scope: "local",
        version: def.version,
        input: def.input,
        variants: { [LOCAL_VARIANT]: members },
    };
    return finish({ scope: "local", name, version: def.version, input: def.input, def, description });
}

export function contractFromDescription(description) {
    const { name, scope, version, input, host } = description;
    if (typeof name !== "string" ||
        (scope !== "remote" && scope !== "local") ||
        !Number.isInteger(version) ||
        (scope === "remote") !== (host !== undefined)) {
        throw new ChordError("invalid", "malformed contract token", { reason: "token" });
    }
    const base = { name, version, input, description, fingerprint: hash64(canonicalJson(description)) };
    return scope === "remote"
        ? { ...base, scope, def: { version, input, host: host, variants: {} } }
        : { ...base, scope, def: { version, input } };
}

export function coverage(provider, consumer) {
    if (provider.name !== consumer.name || provider.scope !== consumer.scope)
        return "different type";
    if (!samePlacement(provider, consumer))
        return "host";
    if (!fits(consumer.input, provider.input))
        return "input";
    for (const [kind, consumerMembers] of Object.entries(consumer.variants)) {
        const providerMembers = provider.variants[kind];
        if (providerMembers === undefined)
            return `variant ${kind} missing`;
        for (const [name, wanted] of Object.entries(consumerMembers)) {
            const offered = providerMembers[name];
            if (offered === undefined || offered.kind !== wanted.kind)
                return `${kind}.${name} missing or of another kind`;
            if (offered.kind === "method" && wanted.kind === "method") {
                // Both take arguments or neither does; a consumer that expects no result accepts any.
                if ((wanted.args === undefined) !== (offered.args === undefined))
                    return `${kind}.${name} arguments`;
                if (wanted.args !== undefined && offered.args !== undefined && !fits(wanted.args, offered.args))
                    return `${kind}.${name} arguments`;
                if (wanted.result !== undefined && (offered.result === undefined || !fits(offered.result, wanted.result)))
                    return `${kind}.${name} result`;
            }
            else if (offered.kind === "state" && wanted.kind === "state") {
                if (!fits(offered.schema, wanted.schema))
                    return `${kind}.${name} state`;
            }
            else if (offered.kind === "opaque" && wanted.kind === "opaque" && offered.id !== wanted.id) {
                return `${kind}.${name} opaque ${offered.id} != ${wanted.id}`;
            }
        }
    }
    return undefined;
}

export function bind(provider, accepts, consumer) {
    if (provider.fingerprint === consumer.fingerprint)
        return undefined;
    // A moved type is another type for its consumers: no adapter reaches across hosts.
    if (!samePlacement(provider.description, consumer.description)) {
        throw new ChordError("contract_mismatch", `${provider.name} lives on ${placementOf(provider.description)}, the consumer expects ${placementOf(consumer.description)}`);
    }
    if (provider.version === consumer.version) {
        const reason = coverage(provider.description, consumer.description);
        if (reason === undefined)
            return undefined;
        throw new ChordError("contract_mismatch", `${provider.name}@${provider.version} does not cover the consumer's description (${reason}); forgotten version bump?`);
    }
    const adapter = accepts?.[consumer.version];
    if (adapter === undefined) {
        throw new ChordError("contract_mismatch", `${provider.name}: provider version ${provider.version}, consumer version ${consumer.version}, no accepts adapter`);
    }
    return adapter;
}

export function takesNoArgs(contract, name) {
    for (const members of Object.values(contract.description.variants)) {
        const member = members[name];
        if (member?.kind === "method")
            return member.args === undefined;
    }
    return false;
}

export function applyImmutableTrusted(target, operations) {
    let root = target;
    const owned = new WeakSet();
    for (const operation of operations) {
        if (operation[0] === "r") {
            root = operation[1];
            continue;
        }
        if (operation[0] === "p" || operation[0] === "m") {
            const copied = copyPath(root, operation[1], operation[1].length, owned);
            root = copied.root;
            if (!Array.isArray(copied.target))
                throw new TypeError("Trusted array operation target is not an array");
            if (operation[0] === "p")
                spliceTrusted(copied.target, operation[2], operation[3], operation[4]);
            else
                permuteTrusted(copied.target, operation[2]);
            continue;
        }
        const path = operation[1];
        const copied = copyPath(root, path, path.length - 1, owned);
        root = copied.root;
        const key = path[path.length - 1];
        switch (operation[0]) {
            case "s":
                defineData(copied.target, key, operation[2]);
                break;
            case "d":
                if (Array.isArray(copied.target)) {
                    if (typeof key !== "number")
                        throw new TypeError("Trusted array deletion key is not numeric");
                    spliceTrusted(copied.target, key, 1, []);
                }
                else
                    Reflect.deleteProperty(copied.target, key);
                break;
            case "a": {
                const current = read(copied.target, key);
                if (typeof current !== "string")
                    throw new TypeError("Trusted append target is not a string");
                defineData(copied.target, key, `${current}${operation[2]}`);
                break;
            }
            case "t": {
                const current = read(copied.target, key);
                if (typeof current !== "string")
                    throw new TypeError("Trusted truncate target is not a string");
                defineData(copied.target, key, current.slice(operation[2]));
                break;
            }
        }
    }
    return root;
}

function copyPath(root, path, length, owned) {
    if (!isContainer(root))
        throw new TypeError("Trusted operation root is not a container");
    let copiedRoot = root;
    if (!owned.has(root)) {
        copiedRoot = shallowCopy(root);
        owned.add(copiedRoot);
    }
    let destination = copiedRoot;
    for (let index = 0; index < length; index++) {
        const segment = path[index];
        const child = read(destination, segment);
        if (!isContainer(child))
            throw new TypeError("Trusted operation path is not a container");
        if (owned.has(child)) {
            destination = child;
            continue;
        }
        const copy = shallowCopy(child);
        defineData(destination, segment, copy);
        owned.add(copy);
        destination = copy;
    }
    return { root: copiedRoot, target: destination };
}

function shallowCopy(value) {
    if (Array.isArray(value))
        return Array.from(value);
    const result = Object.create(Object.getPrototypeOf(value) === null ? null : Object.prototype);
    for (const key of Object.keys(value))
        defineData(result, key, value[key]);
    return result;
}

function read(target, key) {
    return target[key];
}

function defineData(target, key, value) {
    DATA_DESCRIPTOR.value = value;
    Object.defineProperty(target, key, DATA_DESCRIPTOR);
    DATA_DESCRIPTOR.value = undefined;
}

function spliceTrusted(target, start, remove, items) {
    const oldLength = target.length;
    const delta = items.length - remove;
    if (delta > 0) {
        target.length = oldLength + delta;
        target.copyWithin(start + items.length, start + remove, oldLength);
    }
    else if (delta < 0) {
        target.copyWithin(start + items.length, start + remove, oldLength);
        target.length = oldLength + delta;
    }
    for (let index = 0; index < items.length; index++)
        defineData(target, start + index, items[index]);
}

function permuteTrusted(target, permutation) {
    if (target.length !== permutation.length)
        throw new TypeError("Trusted permutation length mismatch");
    const previous = target.slice();
    for (let index = 0; index < permutation.length; index++)
        target[index] = previous[permutation[index]];
}

function isContainer(value) {
    return value !== null && typeof value === "object";
}

function diffArrayRegion(before, after, path, operations, beforeStart, beforeEnd, afterStart, afterEnd, outputStart) {
    if (overflowedBatches.has(operations))
        return;
    while (beforeStart < beforeEnd && afterStart < afterEnd && sameValue(before[beforeStart], after[afterStart])) {
        beforeStart += 1;
        afterStart += 1;
        outputStart += 1;
    }
    while (beforeStart < beforeEnd && afterStart < afterEnd && sameValue(before[beforeEnd - 1], after[afterEnd - 1])) {
        beforeEnd -= 1;
        afterEnd -= 1;
    }
    const beforeCount = beforeEnd - beforeStart;
    const afterCount = afterEnd - afterStart;
    if (beforeCount === 0 && afterCount === 0)
        return;
    if (beforeCount === 0 || afterCount === 0) {
        emitOperation(operations, ["p", path, outputStart, beforeCount, after.slice(afterStart, afterEnd)]);
        return;
    }
    if (beforeCount === afterCount) {
        const positional = [];
        for (let offset = 0; offset < beforeCount; offset++) {
            if (sameValue(before[beforeStart + offset], after[afterStart + offset])) {
                positional.push([beforeStart + offset, afterStart + offset]);
            }
        }
        if (positional.length > 0) {
            processArrayMatches(before, after, path, operations, beforeStart, beforeEnd, afterStart, afterEnd, outputStart, positional);
            return;
        }
    }
    const subsequence = identitySubsequence(before, beforeStart, beforeEnd, after, afterStart, afterEnd);
    if (subsequence !== undefined && subsequence.length > 0) {
        processArrayMatches(before, after, path, operations, beforeStart, beforeEnd, afterStart, afterEnd, outputStart, subsequence);
        return;
    }
    const identity = identityAnchors(before, beforeStart, beforeEnd, after, afterStart, afterEnd);
    if (identity.length > 0) {
        processArrayMatches(before, after, path, operations, beforeStart, beforeEnd, afterStart, afterEnd, outputStart, identity);
        return;
    }
    const semantic = lcsMatches(before.slice(beforeStart, beforeEnd), after.slice(afterStart, afterEnd), semanticallyAligned, MAX_SEMANTIC_CELLS);
    if (semantic !== undefined && semantic.length > 0) {
        const absolute = semantic.map(([beforeIndex, afterIndex]) => [beforeStart + beforeIndex, afterStart + afterIndex]);
        processArrayMatches(before, after, path, operations, beforeStart, beforeEnd, afterStart, afterEnd, outputStart, absolute);
        return;
    }
    if (beforeCount === 1 && afterCount === 1) {
        diffValue(before[beforeStart], after[afterStart], [...path, outputStart], operations);
        return;
    }
    emitOperation(operations, ["p", path, outputStart, beforeCount, after.slice(afterStart, afterEnd)]);
}

export function diffRevisions(before, after) {
    const operations = [];
    diffValue(before, after, [], operations);
    if (overflowedBatches.has(operations))
        return [["r", after]];
    if (operations.length === 0 || operations[0]?.[0] === "r")
        return operations;
    let deltaCost = 2;
    for (const operation of operations)
        deltaCost += operationCost(operation) + 1;
    if (deltaCost < 65_536)
        return operations;
    const snapshotCost = jsonCost(after) + 6;
    return deltaCost >= snapshotCost ? [["r", after]] : operations;
}

export function overlap(a, b, scan, probe = 64, maxCandidates = 8) {
    if (a.length === 0 || b.length === 0 || scan === 0)
        return 0;
    const tail = a.length > scan ? a.slice(a.length - scan) : a;
    // A probe of length h can only find overlaps of at least h — the head must
    // actually occur in `a`. So try a long head first (few candidates, and it
    // catches the large overlaps a rolling window produces), then fall back to one
    // character, which finds any overlap at the cost of more candidates.
    //
    // Candidates are bounded because repetitive output — a build log, or any run of
    // one character — makes a long head match at thousands of positions. Giving up
    // returns 0, which emits a set: larger, never wrong.
    for (const h of [Math.min(probe, b.length), 1]) {
        const head = b.slice(0, h);
        let tried = 0;
        for (let k = tail.indexOf(head); k !== -1; k = tail.indexOf(head, k + 1)) {
            if (++tried > maxCandidates)
                break;
            const n = tail.length - k;
            if (n <= b.length && tail.slice(k) === b.slice(0, n))
                return n;
        }
        if (h === 1)
            break;
    }
    return 0;
}

export function assertValidOp(op) {
    if (!Array.isArray(op) || op.length === 0)
        throw new TypeError("op is not a tuple");
    switch (op[0]) {
        case "r":
            if (op.length !== 2)
                throw new TypeError("r arity");
            return;
        case "s":
            if (op.length !== 3)
                throw new TypeError("s arity");
            assertPathArg(op[1], true);
            return;
        case "d":
            if (op.length !== 2)
                throw new TypeError("d arity");
            assertPathArg(op[1], true);
            return;
        case "a":
            if (op.length !== 3 || typeof op[2] !== "string")
                throw new TypeError("a shape");
            assertPathArg(op[1], true);
            return;
        case "t":
            if (op.length !== 3 || !Number.isInteger(op[2]) || op[2] < 0)
                throw new TypeError("t shape");
            assertPathArg(op[1], true);
            return;
        case "p": {
            if (op.length !== 5)
                throw new TypeError("p arity");
            assertPathArg(op[1]);
            if (!Number.isInteger(op[2]) || op[2] < 0)
                throw new TypeError("p index");
            if (!Number.isInteger(op[3]) || op[3] < 0)
                throw new TypeError("p remove");
            if (!Array.isArray(op[4]))
                throw new TypeError("p items");
            return;
        }
        case "m":
            if (op.length !== 3)
                throw new TypeError("m arity");
            assertPathArg(op[1]);
            assertPermutation(op[2]);
            return;
        // Silently skipping an unknown verb is how a newer producer's op vanishes.
        default:
            throw new TypeError(`unknown op verb: ${String(op[0])}`);
    }
}

function assertPathArg(p, nonEmpty = false) {
    if (!Array.isArray(p))
        throw new TypeError("path is not an array");
    if (nonEmpty && p.length === 0)
        throw new TypeError("path is empty");
    assertSafePath(p);
}

function assertPermutation(value) {
    if (!Array.isArray(value))
        throw new TypeError("m permutation is not an array");
    const seen = new Uint8Array(value.length);
    for (const index of value) {
        if (!Number.isInteger(index) || index < 0 || index >= value.length || seen[index] !== 0) {
            throw new TypeError("m permutation is not a bijection");
        }
        seen[index] = 1;
    }
}

export function assertValidWireOp(op) {
    if (!Array.isArray(op) || op.length === 0)
        throw new TypeError("op is not a tuple");
    const [verb] = op;
    const okRef = (r) => {
        if (typeof r === "number") {
            if (!Number.isInteger(r) || r < 0)
                throw new TypeError("bad path id");
            return;
        }
        // A string is not a path. Unchecked, `"a".slice(0, -1)` is `""`, so it
        // resolves to the ROOT and writes there — a path that is not a path, accepted.
        if (!Array.isArray(r))
            throw new TypeError("path is not an array");
        assertSafePath(r);
    };
    switch (verb) {
        case "r":
            if (op.length !== 2)
                throw new TypeError("r arity");
            return;
        case "s":
            if (op.length === 3)
                okRef(op[1]);
            else if (op.length !== 2)
                throw new TypeError("s arity");
            return;
        case "d":
            if (op.length === 2)
                okRef(op[1]);
            else if (op.length !== 1)
                throw new TypeError("d arity");
            return;
        case "a":
            if (op.length === 3) {
                okRef(op[1]);
                if (typeof op[2] !== "string")
                    throw new TypeError("a value");
            }
            else if (op.length === 2) {
                if (typeof op[1] !== "string")
                    throw new TypeError("a value");
            }
            else
                throw new TypeError("a arity");
            return;
        case "t":
            if (op.length === 3) {
                okRef(op[1]);
                if (!Number.isInteger(op[2]) || op[2] < 0)
                    throw new TypeError("t count");
            }
            else if (op.length === 2) {
                if (!Number.isInteger(op[1]) || op[1] < 0)
                    throw new TypeError("t count");
            }
            else
                throw new TypeError("t arity");
            return;
        case "p": {
            const [i, r, items] = op.length === 5 ? [op[2], op[3], op[4]] : op.length === 4 ? [op[1], op[2], op[3]] : [];
            if (items === undefined)
                throw new TypeError("p arity");
            if (op.length === 5)
                okRef(op[1]);
            if (!Number.isInteger(i) || i < 0)
                throw new TypeError("p index");
            if (!Number.isInteger(r) || r < 0)
                throw new TypeError("p remove");
            if (!Array.isArray(items))
                throw new TypeError("p items");
            return;
        }
        case "m":
            if (op.length === 3)
                okRef(op[1]);
            else if (op.length !== 2)
                throw new TypeError("m arity");
            assertPermutation(op[op.length - 1]);
            return;
        case "#": {
            if (op.length !== 3 || !Number.isInteger(op[1]) || op[1] < 0 || !Array.isArray(op[2])) {
                throw new TypeError("# shape");
            }
            assertSafePath(op[2]);
            return;
        }
        // Silently skipping an unknown verb is how a newer producer's op vanishes.
        default:
            throw new TypeError(`unknown op verb: ${String(verb)}`);
    }
}

export function assertSafePath(path) {
    for (const seg of path) {
        if (typeof seg === "string") {
            if (RESERVED_SEGMENTS.has(seg))
                throw new UnsafePathError(seg);
        }
        else if (!Number.isInteger(seg) || seg < 0) {
            throw new UnsafePathError(seg);
        }
    }
}

function assertIndexInRange(parent, index) {
    if (index > parent.length)
        throw new UnsafePathError(index);
}

export function apply(target, ops) {
    return applyOps(target, ops);
}

function applyOps(target, ops) {
    let root = target;
    for (const op of ops) {
        assertValidOp(op);
        if (op[0] === "r") {
            // Adopted, not copied. The consumer owns the batch it was handed.
            //
            // Fanning one batch out to several consumers in-process therefore makes
            // their replicas alias each other. That is an ownership rule, not a
            // defect: copy the batch at the fan-out point, or let each consumer
            // decode its own. A batch that crosses a real boundary is already
            // distinct, because serialisation produces fresh objects.
            root = op[1];
            continue;
        }
        const path = op[1];
        assertSafePath(path);
        if (op[0] === "p") {
            const target_ = path.length === 0 ? root : resolve(root, path);
            if (!Array.isArray(target_))
                throw new PathError(path);
            target_.splice(op[2], op[3]);
            const chunkSize = 10_000;
            for (let offset = 0; offset < op[4].length; offset += chunkSize) {
                target_.splice(op[2] + offset, 0, ...op[4].slice(offset, offset + chunkSize));
            }
            continue;
        }
        if (op[0] === "m") {
            const target_ = path.length === 0 ? root : resolve(root, path);
            if (!Array.isArray(target_) || target_.length !== op[2].length)
                throw new PathError(path);
            const previous = target_.slice();
            for (let index = 0; index < op[2].length; index++)
                target_[index] = previous[op[2][index]];
            continue;
        }
        // s/d/a/t can never target the root — the type forbids it.
        const parent = resolve(root, path.slice(0, -1));
        const key = path[path.length - 1];
        if (Array.isArray(parent)) {
            if (typeof key !== "number")
                throw new UnsafePathError(key);
            assertIndexInRange(parent, key);
        }
        // defineProperty rather than assignment: a setter inherited from the prototype
        // chain would otherwise run on write.
        const write = (value) => {
            Object.defineProperty(parent, key, { value, writable: true, enumerable: true, configurable: true });
        };
        const read = () => (Object.hasOwn(parent, key) ? parent[key] : undefined);
        switch (op[0]) {
            case "s":
                write(op[2]);
                break;
            case "d":
                if (Array.isArray(parent)) {
                    if (typeof key !== "number" || key >= parent.length)
                        throw new PathError(path);
                    parent.splice(key, 1);
                }
                else
                    delete parent[key];
                break;
            case "a": {
                const current = read();
                if (typeof current !== "string")
                    throw new PathError(path);
                write(`${current}${op[2]}`);
                break;
            }
            case "t": {
                const current = read();
                if (typeof current !== "string")
                    throw new PathError(path);
                write(current.slice(op[2]));
                break;
            }
        }
    }
    return root;
}

export function applyImmutable(target, ops) {
    return applyImmutableBatches(target, [ops]);
}

export function applyImmutableBatches(target, batches) {
    let root = target;
    const owned = new WeakSet();
    for (const ops of batches) {
        for (const op of ops) {
            assertValidOp(op);
            if (op[0] === "r") {
                root = op[1];
                continue;
            }
            if (op[0] === "p") {
                const appended = appendCopy(root, op, owned);
                if (appended !== undefined) {
                    root = appended;
                    continue;
                }
            }
            root = copyContainers(root, op[0] === "p" || op[0] === "m" ? op[1] : op[1].slice(0, -1), owned);
            root = applyOps(root, [op]);
        }
    }
    return root;
}

function appendCopy(root, op, owned) {
    const [, path, index, deleteCount, items] = op;
    if (deleteCount !== 0)
        return undefined;
    let target = root;
    for (const segment of path) {
        const valid = typeof segment === "string"
            ? !RESERVED_SEGMENTS.has(segment) && isObj(target) && !Array.isArray(target)
            : Number.isInteger(segment) && segment >= 0 && Array.isArray(target);
        if (!valid || !Object.hasOwn(target, segment))
            return undefined;
        target = target[segment];
    }
    if (!Array.isArray(target) || owned.has(target) || index !== target.length)
        return undefined;
    const appended = target.concat(items);
    owned.add(appended);
