export function childControl(channel = process) {
    const send = (message) => {
        // A parent that is gone fails the write (EPIPE); the `disconnect` that follows is how a child notices.
        if (channel.connected)
            channel.send?.({ chord2control: message }, undefined, undefined, ignoreSendError);
    };
    let resolveInit = () => { };
    const init = new Promise((resolve) => {
        resolveInit = resolve;
    });
    const shutdown = new Set();
    channel.on("message", (message) => {
        const control = message?.chord2control;
        if (control?.type === "init")
            resolveInit(control.value);
        if (control?.type === "shutdown")
            for (const handler of shutdown)
                void handler();
    });
    const fatal = (error) => send({
        type: "fatal",
        message: error instanceof Error ? error.message : String(error),
        ...(error instanceof ChordError && error.reason !== undefined ? { reason: error.reason } : {}),
    });
    return {
        init,
        lock: async () => {
            const name = process.env[LOCK_ENV];
            if (name === undefined)
                return;
            try {
                await processLock(name);
            }
            catch (error) {
                fatal(error);
                throw error;
            }
        },
        ready: () => send({ type: "ready" }),
        fatal,
        report: (status) => send({ type: "status", ...status }),
        onShutdown: (handler) => shutdown.add(handler),
    };
}

function checkLifetime(contract, options) {
    const lifetime = options.lifetime ?? "referenced";
    if (lifetime !== "referenced" && lifetime !== "host")
        throw new TypeError(`${contract.name}: unknown lifetime ${String(lifetime)}`);
    if (lifetime !== "host")
        return;
    if (contract.scope !== "local")
        throw new TypeError(`${contract.name}: lifetime "host" needs a local type (remote types are referenced)`);
    if (options.linger !== undefined)
        throw new TypeError(`${contract.name}: an object of lifetime "host" does not linger (it lives as long as the host)`);
    try {
        normalize(contract.input, {}, `${contract.name} input`);
    }
    catch {
        throw new TypeError(`${contract.name}: lifetime "host" needs an input that accepts {} (the object's one address)`);
    }
}

