        const source = this.#readable();
        if (source !== undefined) {
            this.#seen = { value: source.value };
            this.#safe(() => listener(source.value));
        }
        this.bind();
        return () => this.#remove(this.#values, listener);
    }

events(listener) {
        this.#events.add(listener);
        const source = this.#readable();
        if (source !== undefined) {
            const value = source.value;
            this.#seen = { value };
            this.#safe(() => listener({ type: "snap", value }));
        }
        else
            this.#unseen.add(listener);
        this.bind();
        return () => {
            this.#unseen.delete(listener);
            this.#remove(this.#events, listener);
        };
    }

bind() {
        const source = this.#values.size + this.#events.size > 0 ? this.#current() : undefined;
        if (source === this.#source)
            return;
        this.#upstream();
        this.#upstream = noop;
        this.#source = source;
        if (source === undefined)
            return;
        let first = true;
        this.#upstream = source.events((event) => {
            const isFirst = first;
            first = false;
            if (isFirst && this.#unseen.size === 0 && this.#seen !== undefined && event.value === this.#seen.value)
                return;
            this.#seen = { value: event.value };
            const translated = isFirst ? { type: "reset", value: event.value } : event;
            const events = [...this.#events];
            const values = [...this.#values];
            const unseen = new Set(this.#unseen);
            this.#unseen.clear();
            // Queued: a rebind during a commit must not run observers before the commit completes.
            enqueue(() => {
                for (const listener of events) {
                    if (!this.#events.has(listener))
                        continue;
                    const delivered = unseen.has(listener)
                        ? { type: "snap", value: event.value }
                        : translated;
                    this.#safe(() => listener(delivered));
                }
                for (const listener of values)
                    if (this.#values.has(listener))
                        this.#safe(() => listener(event.value));
            });
        });
    }

stop() {
        this.#values.clear();
        this.#events.clear();
        this.#unseen.clear();
        this.bind();
    }

#current() {
        const view = this.#ref.currentView();
        if (view === undefined || !this.#ref.inVariant(view, this.#name))
            return undefined;
        const value = view[this.#name];
        // Cells and derivations, or any readable an `accepts` adapter maps them to.
        return isSource(value) || isReadableLike(value) ? value : undefined;
    }

#readable() {
        const source = this.#current();
        return source === undefined || hydrationOf(source)?.hydrated === false ? undefined : source;
    }

#remove(set, listener) {
        set.delete(listener);
        this.bind();
    }

#safe(fn) {
        try {
            fn();
        }
        catch (error) {
            this.#ref.object.host.report(error);
        }
    }

get variant() {
        const view = this.currentView();
        return view === undefined ? undefined : variantOf(view);
    }

get shape() {
        const installed = this.status === "live" ? this.object.currentInstalled() : undefined;
        const view = installed === undefined ? undefined : this.#safeView(installed);
        if (installed === undefined || view === undefined)
            return undefined;
        return {
            variant: variantOf(view),
            members: Object.keys(view).filter((key) => key !== "variant"),
            contract: installed.service.contract.fingerprint,
        };
    }

onShape(listener) {
        this.shapeListeners.add(listener);
        return () => this.shapeListeners.delete(listener);
    }

onStatus(listener) {
        this.#statusListeners.add(listener);
        return () => this.#statusListeners.delete(listener);
    }

#statusChanged() {
        notifyStatus(this.#statusListeners, this.status, this.error, (error) => this.object.host.report(error));
    }

release() {
        if (this.status === "released" || this.status === "gone")
            return;
        this.status = "released";
        this.#stopReadables();
        this.#statusChanged();
        this.object.release(this);
    }

live() {
        if (this.status !== "loading")
            return;
        this.status = "live";
        this.#statusChanged();
        this.shapeChanged();
    }

gone(error) {
        if (this.status === "released" || this.status === "gone")
            return;
        this.status = "gone";
        this.error = error;
        this.#stopReadables();
        this.#statusChanged();
        for (const listener of [...this.goneListeners])
            listener(error);
    }

shapeChanged() {
        for (const readable of this.readables.values())
            readable.bind();
        const shape = this.shape;
        if (shape === undefined)
            return;
        const listeners = [...this.shapeListeners];
        enqueue(() => {
            for (const listener of listeners) {
                try {
                    listener(shape);
                }
                catch (error) {
                    this.object.host.report(error);
                }
            }
        });
    }

terminalError() {
        return this.status === "gone" ? this.error : new ChordError("released", `reference ${this.address} released`);
    }

viewOf(installed) {
        let adapter = this.bindings.get(installed.service);
        if (!this.bindings.has(installed.service)) {
            adapter = bind(installed.service.contract, installed.service.options.accepts, this.contract);
            this.bindings.set(installed.service, adapter);
        }
        if (adapter === undefined)
            return installed.implementation;
        let view = this.views.get(installed.implementation);
        if (view === undefined) {
            view = adapter(installed.implementation);
            this.views.set(installed.implementation, view);
        }
        return view;
    }

currentView() {
        if (this.status !== "live")
            return undefined;
        const installed = this.object.currentInstalled();
        return installed === undefined ? undefined : this.#safeView(installed);
    }

#safeView(installed) {
        try {
            return this.viewOf(installed);
        }
        catch (error) {
            this.object.host.report(error);
            return undefined;
        }
    }

describe(variant, member) {
        const variants = this.contract.description.variants;
        if (variant !== undefined)
            return variants[variant]?.[member];
        for (const members of Object.values(variants))
            if (members[member] !== undefined)
                return members[member];
        return undefined;
    }

inVariant(view, name) {
        return this.contract.scope !== "remote" || this.describe(variantOf(view), name) !== undefined;
    }

member(name) {
        const declared = this.describe(undefined, name);
        const view = this.currentView();
        const value = view?.[name];
        if (declared?.kind === "method" || (declared === undefined && typeof value === "function")) {
            return this.caller(name);
        }
        if (declared?.kind === "state" || (declared === undefined && (isSource(value) || isReadableLike(value)))) {
            let readable = this.readables.get(name);
            if (readable === undefined) {
                readable = new MemberReadable(this, name);
                this.readables.set(name, readable);
            }
            return readable;
        }
        if (view === undefined || !this.inVariant(view, name))
            return undefined;
        return value instanceof ExposedImpl ? value.resource.value : value;
    }

caller(name) {
        let caller = this.callers.get(name);
        if (caller === undefined) {
            const noArgs = takesNoArgs(this.contract, name);
            caller = (...given) => {
                // A method without arguments is called as `ref.name(ctx)`.
                const [args, ctx] = (noArgs ? [undefined, given[0]] : given);
                if (this.object.host.inFactory > 0) {
                    throw new ChordError("not_ready", `${this.address}.${name} called inside a factory`);
                }
                if (ctx !== undefined && !(ctx instanceof CtxImpl)) {
                    return Promise.reject(invalid("foreign_ctx", "ctx must come from a Chord host"));
                }
                if (ctx === undefined || ctx.holder) {
                    // A code holder (task) starts a fresh root per call, cancelled with the holder.
                    try {
                        ctx?.check(this.object.host);
                    }
                    catch (error) {
                        return Promise.reject(error);
                    }
                    return this.object.host.root((root) => this.object.call(this, name, args, root), {
                        signal: ctx?.signal,
                    });
                }
                return this.object.call(this, name, args, ctx);
            };
            this.callers.set(name, caller);
        }
        return caller;
    }

#stopReadables() {
        for (const readable of this.readables.values())
            readable.stop();
    }

start(after) {
        this.ready = this.#activate(after).then(() => {
            for (const ref of this.refs)
                ref.live();
            this.#maybeIdle();
        }, (cause) => {
            if (this.status === "activating")
                this.status = "failed";
            this.host.forget(this);
            // A ChordError (forbidden, a dependency's error, ...) keeps its code; anything else is `unavailable`.
            const error = asChordError(cause, `activating ${this.address}`);
            for (const ref of this.refs)
                ref.gone(error);
            throw error;
        });
        this.ready.catch(noop);
    }

async #activate(after) {
        await after?.catch(noop);
        const signal = this.activationAbort.signal;
        const abandoned = () => new ChordError("aborted", `${this.address} abandoned`);
        if (signal.aborted)
            throw abandoned();
        const service = this.host.service(this.typeName);
        if (service === undefined)
            throw new ChordError("unavailable", `${this.typeName} is not served`, { reason: "unknown_type" });
        this.service = service;
        const run = this.run(service, undefined);
        try {
            await this.open(run.created.resources, run.created.refs, signal);
            if (signal.aborted)
                throw abandoned();
            await this.waitHydrated(run);
            if (signal.aborted)
                throw abandoned();
            await this.initCells(run, signal);
            if (signal.aborted)
                throw abandoned();
            this.host.checkRegistrations(this, run.decls);
            this.decls = run.decls;
            for (const [retained, services] of this.host.retainedCodeVersions()) {
                if (services.get(this.typeName) === service) {
                    this.implementations.set(retained, {
                        codeVersion: retained,
                        service,
                        implementation: run.implementation,
                        decls: run.decls,
                    });
                }
            }
            const pending = this.host.pendingCodeVersion();
            if (!this.implementations.has(this.host.currentCodeVersion()) &&
                (pending === undefined || !this.implementations.has(pending))) {
                throw new ChordError("superseded", `${this.address}: code changed during activation`);
            }
            for (const derived of run.created.derives)
                derived.attach();
            this.refreshSchemas();
            // Served only by a running reload's pending code version: new code must not run (listeners, tasks,
            // registrations) before that reload commits.
            this.deferredRuntime = !this.implementations.has(this.host.currentCodeVersion());
            if (!this.deferredRuntime) {
                if (run.decls.registrations.size > 0)
                    this.host.registriesChanged(this);
                this.startRuntime();
            }
            // A listener starting up may have released the last reference synchronously: no resurrection.
            if (signal.aborted)
                throw abandoned();
            this.status = "live";
        }
        catch (error) {
            // Invocations started during finalization (listener roots) end before their resources close.
            this.callAbort.abort(error);
            this.stopListeners();
            this.stopTasks();
            const registered = this.decls.registrations.size > 0 && !this.deferredRuntime;
            this.implementations.clear();
            this.decls = new Decls();
            if (registered)
                this.host.registriesChanged();
            await Promise.allSettled([...this.#invocations, ...this.#stopped]);
            await this.unwind(run).catch((cleanup) => this.host.report(cleanup));
            throw error;
        }
        finally {
            this.pending.delete(run.decls);
        }
    }

run(service, previous) {
        const self = new SelfImpl(this, previous);
        const discard = (run) => {
            this.pending.delete(run.decls);
            void this.unwind(run).catch((cleanup) => this.host.report(cleanup));
        };
        this.pending.add(self.run(undefined).decls);
        this.host.inFactory++;
        let implementation;
        try {
            implementation = service.factory(this.input, this.principal, self);
        }
        catch (error) {
            this.host.inFactory--;
            discard(self.run(undefined));
            throw error;
        }
        this.host.inFactory--;
        const run = self.run(implementation);
        try {
            if (implementation instanceof Promise)
                throw invalid("implementation", `${this.typeName}: factories must be synchronous`);
            validateImplementation(service, run.implementation);
        }
        catch (error) {
            discard(run);
            throw error;
        }
        return run;
    }

async open(resources, refs, signal) {
        const opening = new Map();
        const openOne = (resource) => {
            let promise = opening.get(resource);
            if (promise === undefined) {
                promise = (async () => {
                    await Promise.all(resource.deps.map((dep) => !(dep instanceof ResourceImpl) ? dep.ready : resources.includes(dep) ? openOne(dep) : undefined));
                    await resource.open(signal, this.openOrder);
                })();
                opening.set(resource, promise);
            }
            return promise;
        };
        const ready = this.withinReadyTimeout(Promise.all(refs.map((ref) => ref.ready)), () => refs.filter((ref) => ref.status === "loading").map((ref) => ref.address));
        const results = await Promise.allSettled([...resources.map(openOne), ready]);
        const failure = results.find((result) => result.status === "rejected");
        if (failure !== undefined)
            throw failure.reason;
    }

async waitHydrated(run) {
        const exposed = Object.entries(run.implementation ?? {});
        const pending = unhydrated([...run.created.derives, ...exposed.map(([, value]) => value)]);
        if (pending.length === 0)
            return;
        await this.withinReadyTimeout(Promise.all(pending.map((hydration) => hydration.whenHydrated())), () => [
            ...exposed
                .filter(([, value]) => hydrationOf(value)?.hydrated === false)
                .map(([name]) => `${this.address}.${name}`),
            ...run.created.derives
                .filter((derived) => hydrationOf(derived) !== undefined)
                .map((derived) => `derive ${derived.key}`),
        ]);
    }

async withinReadyTimeout(work, waiting) {
        const ms = this.host.readyTimeout;
        if (!Number.isFinite(ms))
            return work;
        let timer;
        const timeout = new Promise((_, reject) => {
            timer = setTimeout(() => {
                const list = waiting();
                reject(new ChordError("unavailable", `${this.address} was not ready after ${ms} ms${list.length === 0 ? "" : `, waiting on ${list.join(", ")}`} (a reference cycle across hosts?)`, { reason: "ready_timeout" }));
            }, ms);
            timer.unref?.();
        });
        timeout.catch(noop);
        try {
            return await Promise.race([work, timeout]);
        }
        finally {
            clearTimeout(timer);
        }
    }

async initCells(run, signal) {
        if (run.created.inits.length === 0)
            return;
        const results = await Promise.allSettled(run.created.inits.map(async ([cell, init]) => {
            const value = await this.host.root((ctx) => init(ctx), { signal });
            if (!signal.aborted)
                cell.initialize(value);
        }));
        const failure = results.find((result) => result.status === "rejected");
        if (failure !== undefined)
            throw failure.reason;
    }

async unwind(run) {
        for (const derived of run.created.derives)
            derived.detach();
        const resources = [...run.created.resources].sort((a, b) => this.openOrder.indexOf(b) - this.openOrder.indexOf(a));
        await runAll([
            ...resources.map((resource) => () => resource.close(this.openOrder)),
            ...run.created.refs.map((ref) => () => ref.release()),
        ], `${this.address}: cleanup failed`);
    }

currentInstalled() {
        return this.implementations.get(this.host.currentCodeVersion()) ?? [...this.implementations.values()].at(-1);
    }

refreshSchemas() {
        const schemas = new Map();
        for (const installed of this.implementations.values()) {
            for (const [source, list] of memberSchemas(installed.service, installed.implementation)) {
                schemas.set(source, [...(schemas.get(source) ?? []), ...list]);
            }
        }
        for (const decls of this.allDecls()) {
            for (const source of [...decls.cells.values(), ...decls.derives.values()])
                source.schemas = schemas.get(source) ?? [];
        }
    }

allDecls() {
        const result = new Set([this.decls, ...this.pending]);
        for (const installed of this.implementations.values())
            result.add(installed.decls);
        return result;
    }

#origin(decl) {
        return resourceOf(decl.source) ?? decl.source;
    }

#listenSource(key, decl) {
        const resource = resourceOf(decl.source);
        const value = resource === undefined ? decl.source : resource.value;
        const source = (decl.select === undefined ? value : decl.select(value));
        if (typeof source?.subscribe !== "function")
            throw invalid("implementation", `listener ${key}: source has no subscribe()`);
        return source;
    }

stageListeners(decls) {
        const fresh = new Map();
        const kept = new Set();
        try {
            for (const [key, decl] of decls.listeners) {
                const origin = this.#origin(decl);
                const previous = this.#subscriptions.get(key);
                if (previous !== undefined && previous.origin === origin && sameSelect(previous.select, decl.select)) {
                    kept.add(key);
                    continue;
                }
                const source = this.#listenSource(key, decl);
                const entry = {
                    origin,
                    select: decl.select,
                    unsubscribe: noop,
                    buffer: [],
                };
                fresh.set(key, entry);
                // State (a readable) is subscribed when the listener activates: it delivers the value current then, not one
                // of the candidate before the commit (a new derivation computes its value at the commit).
                if (isSource(source) || isReadableLike(source)) {
                    entry.buffer = undefined;
                    entry.subscribe = () => {
                        entry.unsubscribe = source.subscribe((event) => this.#deliver(key, event));
                    };
                    continue;
                }
                entry.unsubscribe = source.subscribe((event) => {
                    if (entry.buffer !== undefined)
                        entry.buffer.push(event);
                    else
                        this.#deliver(key, event);
                });
            }
        }
        catch (error) {
            for (const entry of fresh.values())
                entry.unsubscribe();
            throw error;
        }
        return {
            activate: () => {
                for (const [key, subscription] of this.#subscriptions) {
                    if (kept.has(key))
                        continue;
                    subscription.unsubscribe();
                    this.#subscriptions.delete(key);
                }
                for (const [key, entry] of fresh) {
                    this.#subscriptions.set(key, entry);
                    entry.subscribe?.();
                    const buffered = entry.buffer ?? [];
                    entry.buffer = undefined;
                    for (const event of buffered)
                        this.#deliver(key, event);
                }
            },
            discard: () => {
                for (const entry of fresh.values())
                    entry.unsubscribe();
            },
        };
    }

startRuntime() {
        this.stageListeners(this.decls).activate();
        this.startTasks();
    }

startTasks() {
        const run = ++this.#taskRuns;
        const start = () => {
            for (const key of this.decls.tasks.keys())
                this.#startTask(key, this.host.currentCodeVersion());
        };
        if (this.#stopped.size === 0) {
            start();
            return;
        }
        const deadline = this.host.taskStopDeadline;
        let timer;
        const late = new Promise((resolve) => {
            timer = setTimeout(() => resolve(true), deadline);
        });
        const stopped = Promise.allSettled([...this.#stopped]).then(() => false);
        void Promise.race([stopped, late]).then((missed) => {
            clearTimeout(timer);
            if (run !== this.#taskRuns || this.status !== "live")
                return;
            if (missed) {
                this.host.report(new ChordError("aborted", `${this.address}: aborted tasks still running after ${deadline} ms; starting their replacements anyway`));
            }
            start();
        });
    }

stopListeners() {
        for (const subscription of this.#subscriptions.values())
            subscription.unsubscribe();
        this.#subscriptions.clear();
    }

#startTask(key, codeVersion) {
        const fn = this.decls.tasks.get(key);
        if (fn === undefined)
            return;
        const controller = new AbortController();
        const ctx = new CtxImpl(this.host, {
            signals: [controller.signal, this.callAbort.signal],
            rootId: `task:${this.address}:${key}`,
            codeVersion,
            principal: this.host.principal,
            holder: true,
        });
        const done = (async () => {
            try {
                await fn(ctx);
            }
            catch (error) {
                if (!ctx.signal.aborted)
                    this.host.report(error);
            }
            finally {
                ctx.close();
                if (this.#tasks.get(key)?.controller === controller)
                    this.#tasks.delete(key);
            }
        })();
        this.#tasks.set(key, { controller, done });
    }

stopTasks() {
        this.#taskRuns++;
        for (const task of this.#tasks.values()) {
            task.controller.abort(new ChordError("aborted", "task stopped"));
            const done = task.done;
            this.#stopped.add(done);
            void done.finally(() => this.#stopped.delete(done));
        }
        this.#tasks.clear();
    }

#deliver(key, event) {
        enqueue(() => {
            if (this.gate !== undefined) {
                this.gate.queue.push({ key, event });
                return;
            }
            const decl = this.decls.listeners.get(key);
            if (decl === undefined || (this.status !== "live" && this.status !== "activating"))
                return;
            const invocation = this.host.root((root) => {
                this.lease(root);
                const child = root.child(this);
                return this.#invoke(async () => {
                    try {
                        await decl.fn(event, child);
                    }
                    finally {
                        child.close();
                    }
                });
            });
            invocation.catch((error) => this.host.report(error));
        });
    }

openGate() {
        const gate = this.gate;
        this.gate = undefined;
        for (const { key, event } of gate?.queue ?? [])
            this.#deliver(key, event);
    }

admit(ctx) {
        if (this.host.failed !== undefined) {
            throw new ChordError("unavailable", `${this.host.name} failed and admits no work`, { reason: "host_failed" });
        }
        if (!this.host.hasCodeVersion(ctx.codeVersion))
            throw new ChordError("superseded", `code version ${ctx.codeVersion} is retired`);
        if (ctx.codeVersion < this.minCodeVersion) {
            throw new ChordError("upgrade_conflict", `${this.address} was upgraded in code version ${this.minCodeVersion}`);
        }
        if (this.gate !== undefined && !this.gate.grandfathered.has(ctx.rootId)) {
            throw new ChordError("upgrade_conflict", `${this.address} is being upgraded`);
        }
    }

lease(ctx) {
        if (this.leases.has(ctx.rootId))
            return;
        this.leases.set(ctx.rootId, ctx.codeVersion);
        this.host.touch(ctx.rootId, this);
    }

async call(ref, name, args, ctx) {
        ctx.check(this.host);
        if (ref.status === "released" || ref.status === "gone")
            throw ref.terminalError();
        if (ref.status === "loading")
            await raceSignal(ref.ready, ctx.signal);
        if (ref.status !== "live" || this.status !== "live") {
            throw ref.status === "live"
                ? new ChordError("gone", `${this.address} is ${this.status}`)
                : ref.terminalError();
        }
        this.admit(ctx);
        const installed = this.implementations.get(ctx.codeVersion);
        if (installed === undefined)
            throw new ChordError("superseded", `${this.address} has no implementation for code version ${ctx.codeVersion}`);
        const view = ref.viewOf(installed);
        const variant = variantOf(view);
        const wanted = ref.describe(ref.contract.scope === "remote" ? variant : LOCAL_VARIANT, name);
        const fn = view[name];
        if (typeof fn !== "function" || (ref.contract.scope === "remote" && wanted?.kind !== "method")) {
            throw new ChordError("not_in_variant", `${this.address}: ${name} is not a method of variant ${variant ?? "(local)"}`);
        }
        const direct = view === installed.implementation;
        const schema = direct
            ? installed.service.contract.description.variants[variant ?? LOCAL_VARIANT]?.[name]
            : wanted;
        const method = schema?.kind === "method" ? schema : undefined;
        const validated = ref.contract.scope === "remote" ? method : undefined;
        // No arguments: the handler takes only ctx. No result (void): the caller gets undefined, whatever it returned.
        const takesArgs = method === undefined || method.args !== undefined;
        const returns = method === undefined || method.result !== undefined;
        let input;
        if (takesArgs) {
            // The additive rule assumes a consumer sends only what its own schema knows, and a provider sees only what its
            // schema knows: strip with both before validating.
            const own = ref.contract.scope === "remote" && wanted?.kind === "method" ? wanted.args : undefined;
            const sent = own === undefined ? args : Value.Clean(own, Value.Clone(args));
            input = validated?.args ? Value.Clean(validated.args, Value.Clone(sent)) : sent;
            if (validated?.args)
                assertValid("args", `${this.address}.${name} args`, validated.args, input);
        }
        this.lease(ctx);
        const child = ctx.child(this);
        let result;
        try {
            result = await this.#invoke(() => takesArgs
                ? fn(input, child)
                : fn(child));
        }
        finally {
            child.close();
        }
        if (!returns)
            return undefined;
        if (validated?.result)
            assertValid("result", `${this.address}.${name} result`, validated.result, result);
        return result;
    }

#invoke(fn) {
        const invocation = (async () => fn())();
        this.#invocations.add(invocation);
        const done = () => {
            this.#invocations.delete(invocation);
            if (this.#invocations.size === 0)
                this.#maybeIdle();
        };
        invocation.then(done, done);
        return invocation;
    }

rootEnded(rootId) {
        this.leases.delete(rootId);
        const gate = this.gate;
        if (gate?.grandfathered.delete(rootId) && gate.grandfathered.size === 0)
            gate.drained();
    }

addRef(ref) {
        this.refs.add(ref);
        if (this.#linger !== undefined)
            clearTimeout(this.#linger);
        this.#linger = undefined;
    }

release(ref) {
        if (this.refs.delete(ref))
            this.#maybeIdle();
    }

#maybeIdle() {
        if (this.refs.size > 0 || this.#invocations.size > 0 || this.#linger !== undefined)
            return;
        if (this.status === "activating") {
            this.#background(this.dispose(false));
            return;
        }
        if (this.status !== "live")
            return;
        const linger = this.service?.options.linger ?? 0;
        if (linger <= 0) {
            this.#background(this.dispose(false));
            return;
        }
        this.#linger = setTimeout(() => {
            this.#linger = undefined;
            if (this.refs.size === 0 && this.#invocations.size === 0 && this.status === "live") {
                this.#background(this.dispose(false));
            }
        }, linger);
        this.#linger.unref?.();
    }

#background(disposal) {
        disposal.catch((error) => this.host.report(error));
    }

dispose(forced, reason) {
        this.#disposal ??= this.#dispose(forced, reason);
        return this.#disposal;
    }

async #dispose(forced, reason) {
        const wasActivating = this.status === "activating";
        this.status = "disposing";
        this.host.forget(this);
        if (this.#linger !== undefined)
            clearTimeout(this.#linger);
        this.#linger = undefined;
        const error = reason ?? new ChordError("gone", `${this.address} was disposed`);
        if (forced) {
            for (const ref of this.refs)
                ref.gone(error);
            this.callAbort.abort(error);
        }
        this.activationAbort.abort(error);
        if (wasActivating)
            await this.ready.catch(noop);
        for (const ref of this.refs)
            ref.gone(error);
        const decls = this.allDecls();
        this.stopTasks();
        this.stopListeners();
        await Promise.allSettled([...this.#invocations]);
        const registered = [...decls].some((set) => set.registrations.size > 0) && !this.deferredRuntime;
        this.implementations.clear();
        this.decls = new Decls();
        if (registered)
            this.host.registriesChanged();
        const refs = new Set();
        for (const set of decls) {
            for (const derived of set.derives.values())
                derived.detach();
            for (const ref of set.refs.values())
                refs.add(ref);
        }
        try {
            await runAll([
                () => Promise.allSettled([...this.#stopped]),
                ...[...this.openOrder].reverse().map((resource) => () => resource.close(this.openOrder)),
                ...[...refs].map((ref) => () => ref.release()),
            ], `${this.address}: disposal failed`);
        }
        finally {
            this.status = "disposed";
            this.host.disposed(this);
        }
    }

export function memberSchemas(service, implementation) {
    const schemas = new Map();
    const contract = service.contract;
    if (contract.scope !== "remote")
        return schemas;
    const members = contract.description.variants[variantOf(implementation) ?? ""] ?? {};
    for (const [name, description] of Object.entries(members)) {
        const source = implementation[name];
        if (description.kind !== "state" || !isSource(source))
            continue;
        schemas.set(source, [...(schemas.get(source) ?? []), description.schema]);
    }
    return schemas;
}

function validateImplementation(service, implementation) {
    const contract = service.contract;
    const fail = (message) => {
        throw invalid("implementation", `${contract.name}: ${message}`);
    };
    if (implementation === null || typeof implementation !== "object")
        fail("factory must return an object");
    let members;
    if (contract.scope === "remote") {
        const variant = implementation.variant;
        if (typeof variant !== "string" || contract.description.variants[variant] === undefined)
            fail(`unknown variant ${String(variant)}`);
        members = contract.description.variants[variant];
        for (const key of Object.keys(implementation))
            if (key !== "variant" && members[key] === undefined)
                fail(`${key} is not in variant ${String(variant)}`);
    }
    else {
        members = contract.description.variants[LOCAL_VARIANT] ?? {};
    }
    for (const [name, description] of Object.entries(members)) {
        const value = implementation[name];
        if (description.kind === "method" && typeof value !== "function")
            fail(`${name} must be a method`);
        if (description.kind === "state" && !isSource(value) && !isReadableLike(value)) {
            fail(`${name} must be a cell, a derivation or a held object's state member`);
        }
        if (description.kind === "opaque" && value === undefined)
            fail(`${name} is missing`);
    }
}

run(implementation) {
        return { implementation: implementation, decls: this.#decls, created: this.#created };
    }

#unique(map, kind, name) {
        if (typeof name !== "string" || name === "")
            throw new TypeError(`${kind} needs a name`);
        if (map.has(name))
            throw invalid("duplicate", `${this.#object.typeName}: duplicate ${kind} name ${name}`);
    }

state(name, schema, initial, options = {}) {
        this.#unique(this.#decls.cells, "state", name);
        const version = options.version ?? 1;
        if (!Number.isInteger(version) || version < 1)
            throw new TypeError(`state ${name}: version must be a positive integer`);
        const host = this.#object.host;
        // A JSON value never holds a function: an object with a function `init` is the initializer, not a value.
        const init = isStateInit(initial) ? initial.init : undefined;
        let cell = this.#previous?.cells.get(name);
        if (cell === undefined) {
            cell = new Cell(name, schema, init === undefined ? { value: initial } : undefined, this.#object.guard, {
                dev: host.dev,
                report: (error) => host.report(error),
            });
            if (init !== undefined)
                this.#created.inits.push([cell, init]);
        }
        this.#decls.cells.set(name, cell);
        this.#decls.cellSchemas.set(name, schema);
        this.#decls.cellVersions.set(name, version);
        if (options.migrate !== undefined)
            this.#decls.cellMigrations.set(name, options.migrate);
        return cell;
    }

get(type, input, options) {
        const host = this.#object.host;
        // A prepare rerun (recording mode) binds new references against the reload's pending contracts: a breaking provider
        // change and its updated consumer reload together.
        const candidate = this.#previous !== undefined;
        const address = host.addressOf(type, input, options?.principal ?? host.principal, candidate);
        const declared = this.#decls.refs.get(address);
        if (declared !== undefined) {
            if (declared.contract.fingerprint !== type.fingerprint) {
                throw invalid("duplicate", `${this.#object.typeName}: ${type.name} held twice with different contracts`);
            }
            return declared.proxy;
        }
        const existing = this.#previous?.refs.get(address);
        if (existing !== undefined &&
            existing.contract.fingerprint === type.fingerprint &&
            existing.status !== "gone" &&
            existing.status !== "released") {
            this.#decls.refs.set(address, existing);
            return existing.proxy;
        }
        const ref = host.acquire(type, input, options, "object", this.#object, candidate);
        this.#decls.refs.set(address, ref);
        this.#created.refs.push(ref);
        return ref.proxy;
    }

resource(name, declaration) {
        this.#unique(this.#decls.resources, "resource", name);
        if (!Number.isInteger(declaration.version))
            throw new TypeError(`resource ${name}: version must be an integer`);
        const deps = (declaration.deps ?? []).map((dep) => {
            const resolved = refOf(dep) ?? resourceOf(dep);
            if (resolved === undefined) {
                throw new TypeError(`resource ${name}: deps must be references or resources of this object`);
            }
            return resolved;
        });
        const existing = this.#previous?.resources.get(name);
        const kept = existing !== undefined &&
            existing.spec.version === declaration.version &&
            existing.exclusive === (declaration.exclusive === true) &&
            existing.deps.length === deps.length &&
            existing.deps.every((dep, index) => dep === deps[index]);
        const resource = kept ? existing : new ResourceImpl(name, declaration, deps);
        if (kept)
            this.#decls.adopted.set(existing, declaration);
        else
            this.#created.resources.push(resource);
        this.#decls.resources.set(name, resource);
        return new ResourceFacade(resource, this.#object.host);
    }

on(name, source, ...rest) {
        this.#unique(this.#decls.listeners, "listener", name);
        const [select, fn] = rest.length === 1 ? [undefined, rest[0]] : [rest[0], rest[1]];
        if (typeof fn !== "function")
            throw new TypeError(`listener ${name}: the handler must be a function`);
        if (select !== undefined && typeof select !== "function")
            throw new TypeError(`listener ${name}: select must be a function`);
        this.#decls.listeners.set(name, {
            source,
            select: select,
            fn: fn,
        });
    }

task(fn) {
        if (typeof fn !== "function")
            throw new TypeError("a task must be a function");
        this.#decls.tasks.set(`#${this.#decls.tasks.size}`, fn);
    }

derive(sources, fn) {
        if (typeof fn !== "function")
            throw new TypeError("a derivation needs a function");
        const host = this.#object.host;
        const key = `#${this.#decls.derives.size}`;
        const derived = new Derived(key, sources, fn, {
            dev: host.dev,
            report: (error) => host.report(error),
        });
        this.#created.derives.push(derived);
        this.#decls.derives.set(key, derived);
        return derived;
    }

expose(resource) {
        const resolved = resourceOf(resource);
        if (resolved === undefined || ![...this.#decls.resources.values()].includes(resolved)) {
            throw new TypeError("expose takes a resource declared by this object");
        }
        return new ExposedImpl(resolved);
    }

register(registry, entries) {
        if (!this.#object.hostLifetime)
            throw invalid("not_host_lifetime", `${this.#object.typeName}: only objects of lifetime "host" may register`);
        for (const [key, value] of Object.entries(entries)) {
            const id = `${registry.name}\u0000${key}`;
            this.#unique(this.#decls.registrations, "register", id);
            this.#decls.registrations.set(id, { registry: registry, key, value });
        }
    }

export function sanitizeOutput(text) {
    return text.replace(INVALID_OUTPUT, "");
}

export function boundOutput(text, limits) {
    const bytes = encoder.encode(text);
    const [from, to] = limits.retain === "head" ? headRange(bytes, limits) : tailRange(bytes, limits);
    const kept = bytes.subarray(from, to);
    return {
        text: kept.length === bytes.length ? text : decoder.decode(kept),
        bytes: kept.length,
        droppedBytes: bytes.length - kept.length,
        droppedLines: lineCount(bytes) - lineCount(kept),
    };
}

function headRange(bytes, limits) {
    if (limits.maxLines === 0 || limits.maxBytes === 0)
        return [0, 0];
    let end = bytes.length;
    let lines = 0;
    for (let index = bytes.indexOf(NEWLINE); index !== -1; index = bytes.indexOf(NEWLINE, index + 1)) {
        if (++lines === limits.maxLines) {
            end = index + 1;
            break;
        }
    }
    if (end > limits.maxBytes) {
        const newline = bytes.lastIndexOf(NEWLINE, limits.maxBytes - 1);
        end = newline === -1 ? characterEnd(bytes, limits.maxBytes) : newline + 1;
    }
    return [0, end];
}

function tailRange(bytes, limits) {
    if (limits.maxLines === 0 || limits.maxBytes === 0)
        return [bytes.length, bytes.length];
    // A trailing newline ends the last line rather than starting another.
    const last = bytes[bytes.length - 1] === NEWLINE ? bytes.length - 2 : bytes.length - 1;
    let start = 0;
    let lines = 1;
    for (let index = last < 0 ? -1 : bytes.lastIndexOf(NEWLINE, last); index !== -1;) {
        if (lines === limits.maxLines) {
            start = index + 1;
            break;
        }
        lines++;
        index = index === 0 ? -1 : bytes.lastIndexOf(NEWLINE, index - 1);
    }
    if (bytes.length - start > limits.maxBytes) {
        const from = bytes.length - limits.maxBytes;
        const newline = bytes.indexOf(NEWLINE, from - 1);
        // The first line starting inside the byte window, or a cut of the last line when it alone is too long.
        start = newline !== -1 && newline + 1 < bytes.length ? newline + 1 : characterStart(bytes, from);
    }
    return [start, bytes.length];
}

export function characterEnd(bytes, index) {
    let end = index;
    while (end > 0 && ((bytes[end] ?? 0) & 0xc0) === 0x80)
        end--;
    return end;
}

function characterStart(bytes, index) {
    let start = index;
    while (start < bytes.length && ((bytes[start] ?? 0) & 0xc0) === 0x80)
        start++;
    return start;
}

function lineCount(bytes) {
    if (bytes.length === 0)
        return 0;
    let newlines = 0;
    for (let index = bytes.indexOf(NEWLINE); index !== -1; index = bytes.indexOf(NEWLINE, index + 1))
        newlines++;
    return newlines + (bytes[bytes.length - 1] === NEWLINE ? 0 : 1);
}

get storedBytes() {
        return this.#storedBytes;
    }

push(chunk, skipped) {
        // Bytes of an incomplete character from an earlier byte chunk come first.
        const pending = typeof chunk === "string" || skipped !== undefined ? this.#decoder.decode() : "";
        let text = typeof chunk === "string" ? chunk : this.#decoder.decode(chunk, { stream: true });
        const first = !this.#started && pending === "" && skipped === undefined;
        if (pending !== "" || text !== "" || skipped !== undefined)
            this.#started = true;
        if (first && typeof chunk !== "string" && text.startsWith("\ufeff"))
            text = text.slice(1);
        if (skipped === undefined)
            return this.#accept(pending + text);
        if (this.#limits.retain !== "tail")
            throw new Error("Skipped output requires tail retention");
        this.#accept(pending);
        this.#skip(skipped);
        this.#accept(text);
        return true;
    }

#skip(skipped) {
        if (skipped.bytes === 0)
            return;
        this.#totalBytes += skipped.bytes;
        this.#totalNewlines += skipped.newlines;
        this.#endsWithNewline = skipped.endsWithNewline;
        this.#chunks = [];
        this.#storedBytes = 0;
        this.#storedNewlines = 0;
    }

end() {
        this.#accept(this.#decoder.decode());
    }

#accept(text) {
        if (text.length === 0)
            return false;
        const bytes = utf8ByteLength(text);
        const newlines = countNewlines(text);
        this.#totalBytes += bytes;
        this.#totalNewlines += newlines;
        this.#endsWithNewline = text.endsWith("\n");
        if (this.#full)
            return true;
        this.#chunks.push({ text, bytes, newlines });
        this.#storedBytes += bytes;
        this.#storedNewlines += newlines;
        if (this.#limits.retain === "head") {
            // Nothing past a full window is ever needed.
            this.#full = this.#storedBytes > this.#limits.maxBytes || this.#storedNewlines >= this.#limits.maxLines;
            return true;
        }
        // Drop leading chunks while the rest still holds more than a window: more than `maxBytes` bytes or `maxLines`
        // newlines, plus one, so the window's line start can still be found. Each chunk is dropped once.
        while (this.#chunks.length > 1) {
            const first = this.#chunks[0];
            const bytesAfter = this.#storedBytes - first.bytes;
            const newlinesAfter = this.#storedNewlines - first.newlines;
            if (bytesAfter <= this.#limits.maxBytes + 1 && newlinesAfter <= this.#limits.maxLines + 1)
                break;
            this.#chunks.shift();
            this.#storedBytes = bytesAfter;
            this.#storedNewlines = newlinesAfter;
        }
        return true;
    }

snapshot() {
        const stored = this.#chunks.length === 1 ? this.#chunks[0].text : this.#chunks.map((chunk) => chunk.text).join("");
        const kept = boundOutput(stored, this.#limits);
        const storedLines = lines(this.#storedNewlines, stored === "" || stored.endsWith("\n"));
        const keptLines = storedLines - kept.droppedLines;
        // Tail windows never reach back before this one, but finding a later window's first line needs what precedes it:
        // keep the shortest suffix longer than the window by a byte or a line, as `#accept` does.
        if (this.#limits.retain === "tail" || this.#chunks.length > 1) {
            const text = this.#limits.retain === "tail" ? tailMargin(stored, this.#limits) : stored;
            const bytes = this.#limits.retain === "tail" ? utf8ByteLength(text) : this.#storedBytes;
            this.#chunks = text === "" ? [] : [{ text, bytes, newlines: countNewlines(text) }];
            this.#storedBytes = bytes;
            this.#storedNewlines = this.#chunks[0]?.newlines ?? 0;
        }
        return {
            text: sanitizeOutput(kept.text),
            droppedBytes: this.#totalBytes - kept.bytes,
            droppedLines: lines(this.#totalNewlines, this.#endsWithNewline) - keptLines,
        };
    }

function tailMargin(text, limits) {
    const bytes = encoder.encode(text);
    const byteStart = bytes.length > limits.maxBytes ? characterEnd(bytes, bytes.length - limits.maxBytes - 1) : 0;
    let lineStart = 0;
    let newlines = 0;
    for (let index = bytes.lastIndexOf(NEWLINE); index !== -1; index = bytes.lastIndexOf(NEWLINE, index - 1)) {
        if (++newlines > limits.maxLines) {
            lineStart = index;
            break;
        }
        if (index === 0)
            break;
    }
    const start = Math.max(byteStart, lineStart);
    return start === 0 ? text : decoder.decode(bytes.subarray(start));
}

function lines(newlines, terminated) {
    return newlines + (terminated ? 0 : 1);
}

export function utf8ByteLength(content) {
    if (runtimeBuffer)
        return runtimeBuffer.byteLength(content, "utf8");
    const firstNonAscii = content.search(nonAsciiPattern);
    if (firstNonAscii === -1)
        return content.length;
    let bytes = firstNonAscii;
    for (let i = firstNonAscii; i < content.length; i++) {
        const code = content.charCodeAt(i);
        if (code <= 0x7f)
            bytes += 1;
        else if (code <= 0x7ff)
            bytes += 2;
        else if (code >= 0xd800 && code <= 0xdbff && i + 1 < content.length) {
            const next = content.charCodeAt(i + 1);
            if (next >= 0xdc00 && next <= 0xdfff) {
                bytes += 4;
                i++;
            }
            else
                bytes += 3;
        }
        else
            bytes += 3;
    }
    return bytes;
}

function countNewlines(text) {
    let count = 0;
    for (let index = text.indexOf("\n"); index !== -1; index = text.indexOf("\n", index + 1))
        count++;
    return count;
}

mark() {
        this.#dirty = true;
        this.#schedule();
    }

markAndWait() {
        const waiter = Promise.withResolvers();
        this.#waiters.push(waiter);
        this.mark();
        return waiter.promise;
    }

async stop() {
        this.#stopped = true;
        clearTimeout(this.#timer);
        this.#timer = undefined;
        await this.#inFlight;
        return this.#waiters.splice(0);
    }

#schedule() {
        if (this.#stopped || this.#timer !== undefined || this.#inFlight !== undefined)
            return;
        const wait = this.#nextAt - Date.now();
        if (wait <= 0)
            this.#flush();
        else
            this.#timer = setTimeout(() => {
                this.#timer = undefined;
                this.#flush();
            }, wait);
    }

#flush() {
        if (this.#stopped || !this.#dirty)
            return;
        this.#dirty = false;
        const waiters = this.#waiters.splice(0);
        const started = Date.now();
        this.#inFlight = this.#write()
            .then((bytes) => {
            this.#nextAt = started + Math.max(this.#minIntervalMs, (bytes * 1000) / PROGRESS_BYTES_PER_SECOND);
            for (const waiter of waiters)
                waiter.resolve();
        }, (error) => {
            this.#nextAt = started + this.#minIntervalMs;
            for (const waiter of waiters)
                waiter.reject(error);
            this.#onError(error);
        })
            .finally(() => {
            this.#inFlight = undefined;
            if (this.#dirty)
                this.#schedule();
        });
    }

export function enqueue(task) {
    queue.push(task);
    drain();
}

export function holdPublications(fn) {
    held++;
    try {
        return fn();
    }
    finally {
        held--;
        drain();
    }
}

function drain() {
    if (draining || held > 0)
        return;
    draining = true;
    try {
        for (let task = queue.shift(); task !== undefined; task = queue.shift())
            task();
    }
    finally {
        draining = false;
    }
}

function dryRun(candidate) {
    const { run, migrated, service, object } = candidate;
    const exposed = memberSchemas(service, run.implementation);
    for (const [cell, value] of migrated) {
        for (const schema of exposed.get(cell) ?? [])
            assertValid("state", `${object.address}: migrated state ${cell.key}`, schema, value);
    }
    const values = new Map(migrated);
    const derives = [...run.decls.derives].sort(([, a], [, b]) => a.seq - b.seq);
    for (const [name, derived] of derives) {
        const value = derived.compute((source) => (values.has(source) ? values.get(source) : candidateValue(source)));
        for (const schema of exposed.get(derived) ?? [])
            assertValid("state", `${object.address}: derivation ${name}`, schema, value);
        values.set(derived, value);
    }
    candidate.derived = values;
}

function candidateValue(source) {
    try {
        return source.value;
    }
    catch (error) {
        if (isChordError(error, "not_ready") || isChordError(error, "not_in_variant"))
            return undefined;
        throw error;
    }
}

export function reloadError(error) {
    const cause = asChordError(error, "reload");
    if (/^reload aborted/.test(cause.message.replace(/^[^:]*: /, "")))
        return cause;
    return new ChordError(cause.code, `reload aborted: ${cause.message}`, {
        cause,
        reason: cause.reason,
        details: cause.details,
    });
}

export async function runReload(host, plugins, options) {
    const reload = await beginReload(host, plugins, options);
    try {
        await reload.prepare();
        return reload.commit();
    }
    finally {
        endReload(host);
    }
}

export async function beginReload(host, plugins, options, codeVersion) {
    if (host.reloading) {
        throw new ChordError("unavailable", "a reload is already running", { reason: "reload_running" });
    }
    host.reloading = true;
    try {
        return new Reload(host, await host.resolve(plugins), options, codeVersion);
    }
    catch (error) {
        host.reloadEnded();
        throw reloadError(error);
    }
}

export function endReload(host) {
    host.reloadEnded();
}

function until(host, ready, ms) {
    if (ready())
        return Promise.resolve(true);
    return new Promise((resolve) => {
        const timer = setTimeout(() => {
            stop();
            resolve(false);
        }, ms);
        const stop = host.watchRetirement(() => {
            if (!ready())
                return;
            clearTimeout(timer);
            stop();
            resolve(true);
        });
    });
}

async prepare() {
        try {
            await this.waitForRetirement();
            this.load();
            this.checkProviders();
            await this.prepareAll();
            // From here new objects of changed types are rejected (upgrade_conflict, retryable) until commit or abort,
            // so the candidate set is final once the activations already in flight have been prepared.
            this.host.gating = this.changed;
            await this.withDeadline(this.prepareAll(), "activations in flight did not finish");
            this.checkRefs();
            this.tables = this.host.buildTables(this.entries());
            await this.gate();
            this.#alive();
            this.#stage();
        }
        catch (error) {
            await this.rollback();
            throw reloadError(error);
        }
    }

summary() {
        const live = [...this.candidates.values()].filter(({ object }) => object.status === "live");
        return {
            codeVersion: this.host.pending?.id ?? this.host.current.id,
            previous: this.host.current.id,
            changed: [...this.changed],
            removed: [...this.removed],
            prepared: live.map(({ object }) => object.address),
            gated: this.gated.map(({ object }) => object.address),
        };
    }

#alive() {
        if (this.rolledBack)
            throw new ChordError("aborted", "reload aborted while preparing", { reason: "aborted" });
    }

#stage() {
        for (const candidate of this.candidates.values()) {
            if (candidate.object.status === "live")
                candidate.staged = candidate.object.stageListeners(candidate.run.decls);
        }
        for (const object of this.host.objects.values()) {
            if (object.status === "live" && object.deferredRuntime)
                this.deferred.set(object, object.stageListeners(object.decls));
        }
    }

async waitForRetirement() {
        const host = this.host;
        const previous = host.previous;
        if (previous === undefined)
            return;
        const deadline = this.options.retireDeadline ?? 5000;
        const gone = () => host.previous !== previous;
        if (!(await until(host, () => gone() || host.retirable(), deadline)) && !gone()) {
            previous.abort.abort(new ChordError("superseded", `code version ${previous.id} was retired`));
            await until(host, () => gone() || previous.roots.size === 0, Math.min(deadline, ABORTED_ROOTS_GRACE));
        }
        if (!gone())
            host.retire();
    }

load() {
        const replaced = new Set([...this.facets.map((facet) => facet.name), ...(this.options.remove ?? [])]);
        const current = this.host.current.services;
        this.services = new Map([...current].filter(([, service]) => !replaced.has(service.facet)));
        for (const facet of this.facets) {
            const run = new AbortController();
            this.facetRuns.set(facet.name, run);
            facet.setup(this.host.facetApi(((type, factory, options = {}) => this.host.serveInto(this.services, makeService(type, factory, options, facet.name))), run.signal));
        }
        for (const [name, service] of this.services)
            if (current.get(name) !== service)
                this.changed.add(name);
        for (const name of current.keys())
            if (!this.services.has(name))
                this.removed.add(name);
        this.host.pending = {
            id: this.host.nextCodeVersionId(this.codeVersion),
            services: this.services,
            tables: new Map(),
            roots: new Map(),
            abort: new AbortController(),
        };
    }

async withDeadline(promise, what) {
        const deadline = this.options.gateDeadline ?? 5000;
        let timer;
        const timeout = new Promise((_, reject) => {
            timer = setTimeout(() => reject(new ChordError("aborted", `${what} within ${deadline} ms`, { reason: "deadline" })), deadline);
        });
        try {
            return await Promise.race([promise, timeout]);
        }
        finally {
            clearTimeout(timer);
        }
    }

checkProviders() {
        for (const name of this.changed) {
            const next = this.services.get(name).contract;
            const old = this.host.current.services.get(name)?.contract;
            if (old === undefined || old.version !== next.version)
                continue;
            const reason = coverage(next.description, old.description);
            if (reason !== undefined) {
                throw new ChordError("contract_mismatch", `${name}@${next.version} changed incompatibly without a version bump (${reason})`);
            }
        }
        const facets = new Map(this.host.facets);
        for (const facet of this.facets)
            facets.set(facet.name, facet);
        for (const name of this.options.remove ?? [])
            facets.delete(name);
        for (const facet of facets.values()) {
            for (const token of facet.uses ?? []) {
                const service = this.services.get(token.name);
                if (service !== undefined && this.changed.has(token.name))
                    bind(service.contract, service.options.accepts, token);
            }
        }
    }

async prepareAll() {
        for (;;) {
            const todo = [...this.host.objects.values()].filter((object) => this.changed.has(object.typeName) &&
                !this.candidates.has(object) &&
                object.service !== this.services.get(object.typeName) &&
                (object.status === "live" || object.status === "activating"));
            if (todo.length === 0)
                return;
            await Promise.allSettled(todo.map((object) => object.ready));
            this.#alive();
            for (const object of todo) {
                if (object.status === "live" && object.service !== this.services.get(object.typeName)) {
                    await this.prepareObject(object);
                    this.#alive();
                }
            }
        }
    }

async prepareObject(object) {
        const service = this.services.get(object.typeName);
        const run = object.run(service, object.decls);
        const candidate = {
            object,
            service,
            run,
            reasons: [],
            atGate: [],
            replaced: [],
            migrated: new Map(),
            derived: new Map(),
            staged: undefined,
        };
        this.candidates.set(object, candidate);
        // Each cell carries its own version: a raised one gates and migrates, a schema change without one is refused.
        for (const [name, cell] of run.decls.cells) {
            if (object.decls.cells.get(name) !== cell)
                continue;
            const from = object.decls.cellVersions.get(name) ?? 1;
            const to = run.decls.cellVersions.get(name) ?? 1;
            if (to < from)
                throw invalid("state", `${object.address}: version of state ${name} lowered from ${from} to ${to}`);
            if (to > from)
                candidate.reasons.push(`state ${name} version ${from} -> ${to}`);
            else if (!deepEqual(cell.schema, run.decls.cellSchemas.get(name)))
                throw invalid("state", `${object.address}: schema of state ${name} changed without a version bump`);
        }
        const deferred = new Set();
        for (const resource of run.created.resources) {
            if (resource.exclusive || resource.deps.some((dep) => deferred.has(dep)))
                deferred.add(resource);
        }
        for (const resource of deferred) {
            candidate.atGate.push(resource);
            const old = object.decls.resources.get(resource.key);
            if (resource.exclusive && old?.exclusive && old.state === "open")
                candidate.replaced.push(old);
        }
        if (deferred.size > 0)
            candidate.reasons.push("exclusive resource replaced");
        await object.open(run.created.resources.filter((resource) => !deferred.has(resource)), run.created.refs, this.abort.signal);
        await object.waitHydrated(run);
        // Cells this reload adds read their first value once the new resources are open (gated objects: at the gate);
        // the derivations over them are checked after.
        if (candidate.reasons.length === 0) {
            await object.initCells(run, this.abort.signal);
            dryRun(candidate);
        }
    }

checkRefs() {
        const dropped = new Set();
        for (const { object, run } of this.candidates.values()) {
            for (const ref of object.decls.refs.values())
                if (![...run.decls.refs.values()].includes(ref))
                    dropped.add(ref);
        }
        for (const object of this.host.objects.values()) {
            const service = this.services.get(object.typeName);
            if (service === undefined || !this.changed.has(object.typeName))
                continue;
            for (const ref of object.refs) {
                // The host's bootstrap reference follows this provider at commit; it is not an old-code consumer.
                if (ref === this.host.hostObjects.get(object.typeName))
                    continue;
                if (!dropped.has(ref) && ref.owner !== "client")
                    bind(service.contract, service.options.accepts, ref.contract);
            }
        }
    }

entries() {
        return this.host
            .liveDecls(true)
            .filter(([object]) => !this.removed.has(object.typeName))
            .map(([object, decls]) => [object, this.candidates.get(object)?.run.decls ?? decls]);
    }

async gate() {
        this.gated = [...this.candidates.values()].filter((candidate) => candidate.reasons.length > 0 && candidate.object.status === "live");
        const drained = this.gated.map(({ object }) => {
            const grandfathered = new Set(object.leases.keys());
            return new Promise((resolve) => {
                object.gate = { grandfathered, queue: [], drained: resolve };
                object.stopTasks();
                if (grandfathered.size === 0)
                    resolve();
            });
        });
        const deadline = this.options.gateDeadline ?? 5000;
        let timer;
        const timedOut = await Promise.race([
            Promise.all(drained).then(() => false),
            new Promise((resolve) => {
                timer = setTimeout(() => resolve(true), deadline);
            }),
        ]);
        clearTimeout(timer);
        if (timedOut) {
            const blocking = this.gated.flatMap(({ object }) => [...(object.gate?.grandfathered ?? [])]);
            throw new ChordError("aborted", `gate deadline (${deadline} ms) missed; blocking roots: ${blocking.join(", ")}`, {
                reason: "gate_deadline",
                details: { blocking },
            });
        }
        this.#alive();
        for (const candidate of this.gated) {
            const { object } = candidate;
            for (const old of candidate.replaced) {
                // Owned by the rollback before closing: a failing close must still be restored.
                this.closed.push([object, old]);
                await old.close(object.openOrder);
            }
            await object.open(candidate.atGate, [], this.abort.signal);
            this.#alive();
            await object.initCells(candidate.run, this.abort.signal);
            this.#alive();
        }
        for (const candidate of this.gated)
            this.migrate(candidate);
    }

migrate(candidate) {
        const { object, run } = candidate;
        for (const [name, cell] of run.decls.cells) {
            if (object.decls.cells.get(name) !== cell)
                continue;
            const schema = run.decls.cellSchemas.get(name);
            const from = object.decls.cellVersions.get(name) ?? 1;
            const fn = run.decls.cellMigrations.get(name);
            let value;
            if ((run.decls.cellVersions.get(name) ?? 1) > from && fn !== undefined)
                value = fn(structuredClone(cell.value), from);
            else if (!deepEqual(cell.schema, schema))
                value = cell.value;
            else
                continue;
            assertValid("state", `${object.address}: migrated state ${name}`, schema, value);
            candidate.migrated.set(cell, value);
        }
        dryRun(candidate);
    }

async rollback() {
        if (this.rolledBack)
            return;
        this.rolledBack = true;
        this.abort.abort(new ChordError("aborted", "reload aborted"));
        for (const run of this.facetRuns.values())
            run.abort(new ChordError("aborted", "reload aborted"));
        const report = (error) => this.host.report(error);
        for (const candidate of this.candidates.values())
            candidate.staged?.discard();
        for (const staged of this.deferred.values())
            staged.discard();
        for (const { object, run } of this.candidates.values()) {
            object.pending.delete(run.decls);
            await object.unwind(run).catch(report);
        }
        // Replaced exclusive resources are restored; one that cannot be is marked unavailable, never silently closed.
        for (const [object, resource] of this.closed) {
            if (resource.state !== "closed")
                continue;
            await resource.open(new AbortController().signal, object.openOrder).catch((error) => {
                resource.markUnavailable();
                report(new ChordError("unavailable", `${object.address}: resource ${resource.key} could not be restored`, {
                    cause: error,
                }));
            });
        }
        for (const { object } of this.gated) {
            if (object.gate === undefined)
                continue;
            object.openGate();
            object.startTasks();
        }
        // Objects of types this reload would have added lose their code.
        const reason = new ChordError("gone", "reload aborted; type not served");
        for (const object of [...this.host.objects.values()]) {
            if (!this.host.current.services.has(object.typeName))
                await object.dispose(true, reason).catch(report);
        }
        this.host.pending = undefined;
        this.host.gating = undefined;
    }

commit(beforeStart) {
        try {
            return holdPublications(() => {
                const report = this.#publish();
                // Installed, not yet started: the coordinator queues its commit frames here, so nothing this code version
                // starts (tasks, host object activations, then the held listener/registry/state notifications) can reach a child
                // first.
                beforeStart?.();
                for (const start of this.#starts.splice(0))
                    start();
                return report;
            });
        }
        catch (error) {
            this.host.fail(error);
            throw reloadError(error);
        }
    }

#publish() {
        const host = this.host;
        const previous = host.current;
        const next = host.pending;
        host.pending = undefined;
        host.codeVersions.set(next.id, next);
        host.previous = previous;
        host.current = next;
        const prepared = [];
        for (const object of [...host.objects.values()]) {
            if (this.removed.has(object.typeName))
                continue;
            const candidate = this.candidates.get(object);
            if (candidate === undefined) {
                const installed = object.implementations.get(previous.id);
                if (installed !== undefined)
                    object.implementations.set(next.id, { ...installed, codeVersion: next.id });
                continue;
            }
            if (object.status !== "live")
                continue;
            this.install(candidate, next.id);
            prepared.push(object.address);
        }
        for (const { object, run, staged } of this.candidates.values()) {
            if (object.status === "live")
                continue;
            staged?.discard();
            object.pending.delete(run.decls);
            object.unwind(run).catch((error) => host.report(error));
        }
        // Objects of types this reload adds start their runtime now.
        for (const [object, staged] of this.deferred) {
            if (object.status !== "live") {
                staged.discard();
                continue;
            }
            object.deferredRuntime = false;
            staged.activate();
            this.#starts.push(() => object.startTasks());
        }
        host.installTables(next, this.tables, true);
        const reason = new ChordError("gone", "type no longer served");
        for (const object of [...host.objects.values()]) {
            if (this.removed.has(object.typeName))
                object.dispose(true, reason).catch((error) => host.report(error));
        }
        for (const name of this.removed)
            host.hostObjects.delete(name);
        for (const facet of this.facets)
            host.facets.set(facet.name, facet);
        for (const name of this.options.remove ?? [])
            host.facets.delete(name);
        // The replaced and removed runs' signals abort after the install, like other observers.
        for (const [name, run] of this.facetRuns)
            this.#starts.push(() => host.facetRunChanged(name, run));
        for (const name of this.options.remove ?? [])
            this.#starts.push(() => host.facetRunChanged(name, undefined));
        host.gating = undefined;
        for (const [name, service] of this.services) {
            if (hostLifetime(service) && this.changed.has(name) && host.hostObjects.get(name)?.object?.status !== "live") {
                this.#starts.push(() => host.startHostObject(service));
            }
            // A type whose lifetime became "referenced" lives on only while someone else references its object.
            const pinned = host.hostObjects.get(name);
            if (!hostLifetime(service) && pinned !== undefined) {
                host.hostObjects.delete(name);
                this.#starts.push(() => pinned.release());
            }
        }
        return {
            codeVersion: next.id,
            previous: previous.id,
            changed: [...this.changed],
            removed: [...this.removed],
            prepared,
            gated: this.gated.map(({ object }) => object.address),
        };
    }

install(candidate, codeVersion) {
        const { object, run, service } = candidate;
        const gated = candidate.reasons.length > 0;
        object.pending.delete(run.decls);
        object.stopTasks();
        if (gated) {
            // Old derivations would compute over migrated values; the old implementation can no longer run anyway.
            const kept = new Set(run.decls.derives.values());
            for (const derived of object.decls.derives.values())
                if (!kept.has(derived))
                    derived.detach();
        }
        object.decls = run.decls;
        object.service = service;
        // Kept resources close with the new code's `close`; replaced ones keep their own (closed at retirement).
        for (const [resource, declaration] of run.decls.adopted)
            resource.adopt(declaration);
        object.implementations.set(codeVersion, {
            codeVersion,
            service,
            implementation: run.implementation,
            decls: run.decls,
        });
        if (gated) {
            // Old code can never run over migrated state: drop the previous implementation now, not at retirement.
            object.minCodeVersion = codeVersion;
            for (const old of [...object.implementations.keys()])
                if (old !== codeVersion)
                    this.host.retireImplementation(object, old);
        }
        // Schemas first, then the values validated against them in prepare.
        object.refreshSchemas();
        for (const [name, cell] of run.decls.cells) {
            const schema = run.decls.cellSchemas.get(name);
            if (candidate.migrated.has(cell))
                cell.reset(candidate.migrated.get(cell), schema);
            else
                cell.schema = schema;
        }
        const created = new Set(run.created.derives);
        for (const derived of run.created.derives)
            derived.attach(candidate.derived);
        for (const derived of run.decls.derives.values())
            if (!created.has(derived))
                derived.refresh();
        candidate.staged?.activate();
        this.#starts.push(() => object.startTasks());
        object.openGate();
        const pinned = this.host.hostObjects.get(object.typeName);
        if (pinned?.object === object && pinned.contract.fingerprint !== service.contract.fingerprint) {
            const replacement = new RefImpl(object, service.contract, "host");
            // Acquire first: releasing the only reference must not dispose/reopen the surviving host object.
            object.addRef(replacement);
            this.host.hostObjects.set(object.typeName, replacement);
            pinned.release();
        }
        for (const ref of [...object.refs]) {
            // Browser references whose contract no longer binds are told to reload their code (they never block a reload).
            if (ref.owner === "client") {
                try {
                    bind(service.contract, service.options.accepts, ref.contract);
                }
                catch (error) {
                    ref.gone(new ChordError("upgrade_required", `${object.typeName} changed; reload the web facets`, {
                        cause: error,
                    }));
                    object.release(ref);
                    continue;
                }
            }
            ref.shapeChanged();
        }
    }

function deferred() {
    let resolve = noop;
    let reject = noop;
    const promise = new Promise((done, fail) => {
        resolve = done;
        reject = fail;
    });
    promise.catch(noop);
    return { promise, resolve, reject };
}

get ended() {
        return this.status === "ended";
    }

get stateViews() {
        let count = 0;
        for (const view of this.views)
            if (view.wantsState)
                count++;
        return count;
    }

get wantsState() {
        return this.views.size === 0 ? this.stateOn : this.stateViews > 0;
    }

get applied() {
        return this.#applied;
    }

addView(view) {
        this.views.add(view);
        if (this.lingerTimer !== undefined) {
            clearTimeout(this.lingerTimer);
            this.lingerTimer = undefined;
        }
        this.#syncState();
        view.update();
    }

removeView(view) {
        if (!this.views.delete(view))
            return;
        for (const set of this.#listeners.values())
            for (const readable of set)
                if (readable.view === view)
                    set.delete(readable);
        if (this.views.size === 0) {
            this.host.bindingIdle(this);
            return;
        }
        this.#syncState();
    }

#syncState() {
        if (this.ended || this.views.size === 0)
            return;
        const wanted = this.stateViews > 0;
        if (wanted === this.stateOn)
            return;
        this.stateOn = wanted;
        if (!wanted) {
            this.hydrated = false;
            this.members.clear();
            if (this.#pending !== undefined)
                this.#pending.missing.clear();
        }
        if (this.hold !== undefined)
            this.hold.channel.wantState(this.hold.id, wanted);
        for (const view of this.views)
            view.update();
    }

listen(name, readable) {
        let set = this.#listeners.get(name);
        if (set === undefined) {
            set = new Set();
            this.#listeners.set(name, set);
        }
        set.add(readable);
    }

unlisten(name, readable) {
        this.#listeners.get(name)?.delete(readable);
    }

inVariant(name) {
        const variant = this.shape?.variant;
        return variant !== undefined && this.contract.description.variants[variant]?.[name]?.kind === "state";
    }

read(name) {
        if (this.status === "ended")
            throw this.terminalError();
        if (!this.hydrated)
            throw new ChordError("not_ready", `${this.key}.${name} is not hydrated yet`);
        if (!this.inVariant(name))
            throw new ChordError("not_in_variant", `${this.key}: ${name} is not a state member of variant ${this.shape?.variant}`);
        return this.members.get(name)?.value;
    }

whenHydrated() {
        if (this.hydrated)
            return Promise.resolve();
        if (this.ended)
            return Promise.reject(this.terminalError());
        return new Promise((resolve, reject) => this.#hydrationWaiters.add({ resolve, reject }));
    }

#settleHydration(error) {
        const waiters = [...this.#hydrationWaiters];
        this.#hydrationWaiters.clear();
        for (const waiter of waiters) {
            if (error === undefined)
                waiter.resolve();
            else
                waiter.reject(error);
        }
    }

readable(name) {
        return this.status !== "ended" && this.hydrated && this.inVariant(name);
    }

terminalError() {
        return this.error ?? new ChordError("released", `reference ${this.key} released`);
    }

bound(channel, id) {
        this.hold = { channel, id };
        this.stateOn = this.wantsState;
    }

shaped(shape, listed) {
        if (this.ended)
            return;
        const previous = this.#pending;
        const missing = new Set(listed);
        // A newer shape before the older one's snapshots (relays may reorder them): wait for both.
        if (previous !== undefined)
            for (const name of previous.missing)
                missing.add(name);
        const wanted = new Set(this.#stateMembers(shape));
        for (const name of [...missing])
            if (!wanted.has(name) || !this.stateOn)
                missing.delete(name);
        this.#pending = { shape, missing, values: previous?.values ?? new Map() };
        if (missing.size === 0)
            this.#apply();
    }

state(name, frame) {
        if (this.ended)
            return;
        if (frame.as === "error") {
            const error = fromWireError(frame.error);
            // Before the first hydration nobody could read anything: the binding fails instead of waiting forever.
            if (!this.hydrated && this.stateOn) {
                this.gone(error);
                this.close();
            }
            else
                this.host.report(error);
            return;
        }
        const pending = this.#pending;
        if (frame.as === "ops") {
            const target = pending?.values.get(name) ?? this.members.get(name);
            if (target === undefined)
                return;
            const ops = target.decoder.decode(frame.ops ?? []);
            target.value = applyImmutable(target.value, ops);
            if (target === this.members.get(name))
                this.#deliver(name, { type: "ops", ops, value: target.value });
            return;
        }
        const fresh = { value: frame.value, decoder: decoder() };
        if (pending !== undefined && (pending.missing.has(name) || pending.values.has(name))) {
            pending.values.set(name, fresh);
            pending.missing.delete(name);
            if (pending.missing.size === 0)
                this.#apply();
            return;
        }
        if (!this.inVariant(name))
            return;
        this.members.set(name, fresh);
        this.#deliver(name, { type: "reset", value: fresh.value });
    }

gone(error) {
        if (this.ended)
            return;
        this.status = "ended";
        this.error = error;
        this.hold = undefined;
        this.#pending = undefined;
        this.#live.reject(error);
        this.#settleHydration(error);
        for (const view of [...this.views])
            view.end(error);
        this.#listeners.clear();
        this.host.forgetBinding(this);
    }

detached() {
        if (this.ended)
            return;
        this.hold = undefined;
        this.#pending = undefined;
        if (this.status === "live") {
            this.status = "loading";
            this.#live = deferred();
        }
        for (const view of this.views)
            view.update();
    }

close() {
        if (this.lingerTimer !== undefined)
            clearTimeout(this.lingerTimer);
        this.lingerTimer = undefined;
        if (this.hold !== undefined)
            this.hold.channel.release(this.hold.id);
        this.hold = undefined;
        if (this.status !== "ended") {
            this.status = "ended";
            const error = new ChordError("released", `reference ${this.key} released`);
            this.#live.reject(error);
            this.#settleHydration(error);
            for (const view of [...this.views])
                view.end(error);
        }
        this.#pending = undefined;
        this.#listeners.clear();
        this.host.forgetBinding(this);
    }

async call(name, args, ctx) {
        for (;;) {
            if (this.ended)
                throw this.terminalError();
            if (this.status !== "live" || this.hold === undefined)
                await raceSignal(this.#live.promise, ctx.signal);
            const hold = this.hold;
            if (hold === undefined || this.status !== "live")
                continue;
            const variant = this.shape?.variant;
            const description = variant === undefined ? undefined : this.contract.description.variants[variant]?.[name];
            if (description?.kind !== "method") {
                throw new ChordError("not_in_variant", `${this.key}: ${name} is not a method of variant ${variant}`);
            }
            // Send only what the consumer's own schema knows (the additive rule's premise; see ObjectImpl.call).
            const sent = description.args === undefined ? undefined : Value.Clean(description.args, Value.Clone(args));
            return hold.channel.call(hold.id, name, sent, { rootId: ctx.rootId, codeVersion: ctx.codeVersion }, ctx.signal);
        }
    }

#stateMembers(shape) {
        const members = shape.variant === undefined ? undefined : this.contract.description.variants[shape.variant];
        if (members === undefined)
            return [];
        return shape.members.filter((name) => members[name]?.kind === "state");
    }

#apply() {
        const pending = this.#pending;
        if (pending === undefined)
            return;
        this.#pending = undefined;
        this.shape = pending.shape;
        const wanted = new Set(this.#stateMembers(pending.shape));
        for (const name of [...this.members.keys()])
            if (!wanted.has(name))
                this.members.delete(name);
        for (const [name, state] of pending.values)
            if (wanted.has(name))
                this.members.set(name, state);
        this.hydrated = this.stateOn && [...wanted].every((name) => this.members.has(name));
        if (this.hydrated)
            this.#settleHydration();
        this.status = "live";
        this.#applied = true;
        this.#live.resolve();
        for (const view of this.views)
            view.update();
        for (const [name, state] of pending.values) {
            if (wanted.has(name))
                this.#deliver(name, { type: "reset", value: state.value });
        }
        for (const view of [...this.views])
            view.shapeChanged();
    }

#deliver(name, event) {
        const readables = this.#listeners.get(name);
        if (readables === undefined)
            return;
        for (const readable of [...readables])
            readable.deliver(event);
    }

get value() {
        if (this.view.ended)
            throw this.view.terminalError();
        return this.view.binding.read(this.#name);
    }

get [HYDRATION]() {
        const binding = this.view.binding;
        if (binding.hydrated)
            return undefined;
        return { hydrated: false, whenHydrated: () => binding.whenHydrated() };
    }

subscribe(listener) {
        this.#values.add(listener);
        this.#attach();
        if (this.#readable())
            this.#safe(() => listener(this.view.binding.members.get(this.#name)?.value));
        return () => this.#remove(this.#values, listener);
    }

events(listener) {
        this.#events.add(listener);
        this.#attach();
        if (this.#readable()) {
            const value = this.view.binding.members.get(this.#name)?.value;
            this.#safe(() => listener({ type: "snap", value }));
        }
        else
            this.#unseen.add(listener);
        return () => {
            this.#unseen.delete(listener);
            this.#remove(this.#events, listener);
        };
    }

deliver(event) {
        for (const listener of [...this.#events]) {
            if (!this.#unseen.delete(listener))
                this.#safe(() => listener(event));
            else if (event.type !== "ops")
                this.#safe(() => listener({ type: "snap", value: event.value }));
        }
        for (const listener of [...this.#values])
            this.#safe(() => listener(event.value));
    }

stop() {
        this.#values.clear();
        this.#events.clear();
        this.#unseen.clear();
        this.view.binding.unlisten(this.#name, this);
    }

#readable() {
        return !this.view.ended && this.view.binding.readable(this.#name);
    }

#attach() {
        if (!this.view.ended)
            this.view.binding.listen(this.#name, this);
    }

#remove(set, listener) {
        set.delete(listener);
        if (this.#values.size + this.#events.size === 0)
            this.view.binding.unlisten(this.#name, this);
    }

#safe(fn) {
        try {
            fn();
        }
        catch (error) {
            this.view.binding.host.report(error);
        }
    }

get contract() {
        return this.binding.contract;
    }

get address() {
        return this.binding.key;
    }

get ended() {
        return this.status === "released" || this.status === "gone";
    }

get variant() {
        return this.binding.shape?.variant;
    }

get shape() {
        return this.binding.shape;
    }

onShape(listener) {
        this.shapeListeners.add(listener);
        return () => this.shapeListeners.delete(listener);
    }

onStatus(listener) {
        this.#statusListeners.add(listener);
        return () => this.#statusListeners.delete(listener);
    }

terminalError() {
        return this.status === "gone" ? this.error : new ChordError("released", `reference ${this.address} released`);
    }

release() {
        if (this.ended)
            return;
        this.status = "released";
        this.#notify();
        this.#settleReady?.reject(new ChordError("released", `reference ${this.address} released`));
        this.#settleReady = undefined;
        for (const readable of this.#readables.values())
            readable.stop();
        this.binding.removeView(this);
    }

update() {
        if (this.ended)
            return;
        const binding = this.binding;
        const live = binding.status === "live" && binding.hold !== undefined && (!this.wantsState || binding.hydrated);
        const next = live ? "live" : "loading";
        if (next === this.status)
            return;
        this.status = next;
        this.#notify();
        if (live) {
            this.#settleReady?.resolve();
            this.#settleReady = undefined;
        }
    }

end(error) {
        if (this.ended)
            return;
        const released = error instanceof ChordError && error.code === "released";
        this.status = released ? "released" : "gone";
        if (!released)
            this.error = error;
        this.#notify();
        this.#settleReady?.reject(error);
        this.#settleReady = undefined;
        for (const readable of this.#readables.values())
            readable.stop();
    }

shapeChanged() {
        const shape = this.binding.shape;
        if (shape === undefined || this.ended)
            return;
        for (const listener of [...this.shapeListeners]) {
            try {
                listener(shape);
            }
            catch (error) {
                this.binding.host.report(error);
            }
        }
    }

#notify() {
        notifyStatus(this.#statusListeners, this.status, this.error, (error) => this.binding.host.report(error));
    }

member(name) {
        const description = Object.values(this.contract.description.variants)
            .map((members) => members[name])
            .find((member) => member !== undefined);
        if (description?.kind === "method")
            return this.#caller(name);
        if (description?.kind === "state") {
            let readable = this.#readables.get(name);
            if (readable === undefined) {
                readable = new ViewReadable(this, name);
                this.#readables.set(name, readable);
            }
            return readable;
        }
        return undefined;
    }

#caller(name) {
        let caller = this.#callers.get(name);
        if (caller === undefined) {
            const noArgs = takesNoArgs(this.contract, name);
            caller = (...given) => {
                // A method without arguments is called as `ref.name(ctx)`.
                const [args, ctx] = (noArgs ? [undefined, given[0]] : given);
                const host = this.binding.host;
                if (host.inFactory > 0)
                    throw new ChordError("not_ready", `${this.address}.${name} called inside a factory`);
                // The same checks as a local reference's caller (RefImpl.caller and ObjectImpl.call): a ctx from another host
                // or one not made by Chord would carry a root this host does not own over its link.
                if (ctx !== undefined && !(ctx instanceof CtxImpl)) {
                    return Promise.reject(invalid("foreign_ctx", "ctx must come from a Chord host"));
                }
                try {
                    ctx?.check(host);
                }
                catch (error) {
                    return Promise.reject(error);
                }
                if (ctx === undefined || ctx.holder) {
                    return host.root((root) => this.#call(name, args, root), { signal: ctx?.signal });
                }
                return this.#call(name, args, ctx);
            };
            this.#callers.set(name, caller);
        }
        return caller;
    }

#call(name, args, ctx) {
        if (this.ended)
            return Promise.reject(this.terminalError());
        return this.binding.call(name, args, ctx);
    }

export function canonicalJson(value) {
    if (value === null || typeof value !== "object")
        return JSON.stringify(value) ?? "null";
    if (Array.isArray(value))
        return `[${value.map((item) => canonicalJson(item)).join(",")}]`;
    const keys = Object.keys(value)
        .filter((key) => value[key] !== undefined)
        .sort();
    return `{${keys.map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(",")}}`;
}

export function hash64(text) {
    let a = 0x811c9dc5;
    let b = 0x01000193 ^ 0x5bd1e995;
    for (let index = 0; index < text.length; index++) {
        const code = text.charCodeAt(index);
        a = Math.imul(a ^ code, 0x01000193);
        b = Math.imul(b ^ code, 0x5bd1e995) ^ (b >>> 13);
    }
    return (a >>> 0).toString(16).padStart(8, "0") + (b >>> 0).toString(16).padStart(8, "0");
}

export function deepEqual(a, b) {
    return a === b || canonicalJson(a) === canonicalJson(b);
}

export function assertValid(reason, what, schema, value) {
    if (Value.Check(schema, value))
        return;
    const errors = [...Value.Errors(schema, value)].slice(0, 3);
    const summary = errors.map((error) => `${error.instancePath || "/"} ${error.message}`).join("; ");
    throw invalid(reason, `${what}: ${summary}`, errors);
}

export function normalize(schema, value, what) {
    const normalized = Value.Clean(schema, Value.Default(schema, Value.Clone(value ?? {})));
    assertValid("input", what, schema, normalized);
    return normalized;
}

export function canonicalIdentity(schema, value) {
    return canonicalJson(stripDefaults(asSchema(schema), value));
}

function stripDefaults(schema, value) {
    if (Array.isArray(value)) {
        const items = schema.items;
        if (Array.isArray(items))
            return value.map((item, index) => stripDefaults(asSchema(items[index]), item));
        return value.map((item) => stripDefaults(asSchema(items), item));
    }
    if (value === null || typeof value !== "object")
        return value;
    const properties = asSchema(schema.properties);
    const result = {};
    for (const [key, item] of Object.entries(value)) {
        const property = asSchema(properties[key]);
        if ("default" in property && deepEqual(property.default, item))
            continue;
        result[key] = stripDefaults(property, item);
    }
    return result;
}

export function fits(subSchema, supSchema) {
    const sub = withoutAnnotations(asSchema(subSchema));
    const sup = withoutAnnotations(asSchema(supSchema));
    if (Object.keys(sup).length === 0)
        return true;
    if (deepEqual(sub, sup))
        return true;
    if (Object.keys(sup).some((key) => !KNOWN.has(key)))
        return false;
    if (sup.additionalProperties !== undefined && typeof sup.additionalProperties !== "boolean")
        return false;
    if (Array.isArray(sub.anyOf))
        return sub.anyOf.every((branch) => fits(branch, sup));
    if (Array.isArray(sup.anyOf))
        return sup.anyOf.some((branch) => fits(sub, branch));
    if ("const" in sup)
        return "const" in sub && deepEqual(sub.const, sup.const);
    if (Array.isArray(sup.enum)) {
        const values = "const" in sub ? [sub.const] : Array.isArray(sub.enum) ? sub.enum : undefined;
        return values?.every((item) => sup.enum.some((allowed) => deepEqual(allowed, item))) ?? false;
    }
    for (const key of CONSTRAINTS)
        if (key in sup && !deepEqual(sub[key], sup[key]))
            return false;
    const supTypes = typesOf(sup);
    const subTypes = typesOf(sub);
    if (supTypes === undefined || subTypes === undefined)
        return false;
    if (!subTypes.every((type) => supTypes.includes(type) || (type === "integer" && supTypes.includes("number")))) {
        return false;
    }
    if ("const" in sub || Array.isArray(sub.enum))
        return true;
    if (subTypes.includes("object") && !objectFits(sub, sup))
        return false;
    if (subTypes.includes("array") && !arrayFits(sub, sup))
        return false;
    if (subTypes.includes("function"))
        return functionFits(sub, sup);
    return true;
}

function objectFits(sub, sup) {
    const subProperties = asSchema(sub.properties);
    const supProperties = asSchema(sup.properties);
    const subRequired = new Set(sub.required ?? []);
    for (const key of sup.required ?? [])
        if (!subRequired.has(key))
            return false;
    for (const [key, property] of Object.entries(supProperties)) {
        if (key in subProperties) {
            if (!fits(subProperties[key], property))
                return false;
        }
        else if (typeof sub.additionalProperties === "object" && !fits(sub.additionalProperties, property)) {
            // The consumer may send this name with any value its `additionalProperties` allows. Open consumer objects
            // are fine: unknown names are stripped with the consumer's own schema before the call (`RecordImpl.call`).
            return false;
        }
    }
    if (sup.additionalProperties === false) {
        if (sub.additionalProperties !== false)
            return false;
        if (Object.keys(subProperties).some((key) => !(key in supProperties)))
            return false;
    }
    const supPatterns = asSchema(sup.patternProperties);
    if (Object.keys(supPatterns).length > 0) {
        // Every value the consumer may put under a matching name must fit, and the consumer must not allow arbitrary
        // extra names (it would then allow any value under a matching one).
        const subPatterns = asSchema(sub.patternProperties);
        if (sub.additionalProperties !== false && Object.keys(subPatterns).length === 0)
            return false;
        for (const [pattern, property] of Object.entries(supPatterns)) {
            const matcher = new RegExp(pattern, "u");
            for (const [key, subProperty] of Object.entries(subProperties)) {
                if (!(key in supProperties) && matcher.test(key) && !fits(subProperty, property))
                    return false;
            }
            if (Object.keys(subPatterns).length > 0 &&
                (!(pattern in subPatterns) || !fits(subPatterns[pattern], property))) {
                return false;
            }
        }
        for (const pattern of Object.keys(subPatterns))
            if (!(pattern in supPatterns))
                return false;
    }
    return true;
}

function arrayFits(sub, sup) {
    if (Array.isArray(sup.items)) {
        if (!Array.isArray(sub.items) || sub.items.length !== sup.items.length)
            return false;
        return sub.items.every((item, index) => fits(item, sup.items[index]));
    }
    if (Array.isArray(sub.items))
        return sub.items.every((item) => fits(item, sup.items));
    return fits(sub.items, sup.items);
}

function functionFits(sub, sup) {
    const subParameters = sub.parameters ?? [];
    const supParameters = sup.parameters ?? [];
    // A function accepting fewer parameters is fine; each shared parameter is contravariant.
    if (subParameters.length > supParameters.length)
        return false;
    if (!subParameters.every((parameter, index) => fits(supParameters[index], parameter)))
        return false;
    return fits(sub.returnType, sup.returnType);
}

push(frame) {
        if (this.#closed)
            return;
        if (this.#pending.length === 100) {
            // A cold replica can queue updates reentrantly before this subscriber's first hydration starts.
            const hydration = this.#started ? undefined : this.#pending[0];
            this.#pending.length = 0;
            if (hydration !== undefined)
                this.#pending.push(hydration);
        }
        this.#pending.push(frame);
    }

drain() {
        if (this.#running || this.#closed)
            return;
        this.#running = true;
        for (let frame = this.#pending.shift(); frame !== undefined; frame = this.#pending.shift()) {
            this.#started = true;
            try {
                const result = this.#listener(frame.value, frame.context, frame.delivery);
                if (isPromiseLike(result)) {
                    void Promise.resolve(result).then(() => this.#resume(), (error) => {
                        this.#report(error);
                        this.#resume();
                    });
                    return;
                }
            }
            catch (error) {
                this.#report(error);
            }
        }
        this.#running = false;
    }

clear() {
        this.#pending.length = 0;
    }

close() {
        this.#closed = true;
        this.clear();
    }

#resume() {
        this.#running = false;
        this.drain();
    }

#report(error) {
        try {
            this.#reportError(toError(error));
        }
        catch (reportError) {
            reportErrorAsync(toError(reportError));
        }
    }

get value() {
        return this.#value;
    }

snapshot() {
        return { value: this.#value, sequence: this.#sequence };
    }

subscribe(listener) {
        const { value, sequence } = this.snapshot();
        const subscriber = new StateSubscriber(listener, this.#reportError);
        this.#listeners.set(subscriber, sequence);
        // Hydration has no caller; it is delivered with the background context.
        subscriber.push({ value, context: BACKGROUND_CONTEXT, delivery: { kind: "hydrate", sequence } });
        subscriber.drain();
        return () => {
            subscriber.close();
            this.#listeners.delete(subscriber);
        };
    }

publish(value, context) {
        this.#value = value;
        this.#sequence += 1;
        this.#publications.push({ value, sequence: this.#sequence, context });
        if (this.#delivering)
            return;
        this.#delivering = true;
        try {
            for (let publication = this.#publications.shift(); publication !== undefined; publication = this.#publications.shift()) {
                const delivery = { kind: "update", sequence: publication.sequence };
                for (const [subscriber, hydratedSequence] of [...this.#listeners]) {
                    if (publication.sequence <= hydratedSequence)
                        continue;
                    subscriber.push({ value: publication.value, context: publication.context, delivery });
                    subscriber.drain();
                }
            }
        }
        finally {
            this.#delivering = false;
        }
    }

get value() {
        return this.#tracker.value;
    }

change(context, mutate) {
        if (this.#changing)
            throw new Error("Replicated state cannot be changed reentrantly from a change callback");
        this.#changing = true;
        let prepared;
        try {
            const change = this.#tracker.beginChange();
            try {
                const outcome = mutate(change.state);
                if (isPromiseLike(outcome)) {
                    void Promise.resolve(outcome).catch(() => undefined);
                    throw new TypeError("Replicated state change callbacks must be synchronous");
                }
                prepared = change.prepare();
            }
            catch (error) {
                change.abort();
                throw error;
            }
        }
        finally {
            this.#changing = false;
        }
        this.#tracker.adopt(prepared);
        if (prepared.ops.length > 0)
            this.#publisher.publish(prepared.value, context);
    }

replace(context, value) {
        if (this.#changing)
            throw new Error("Replicated state cannot be replaced from a change callback");
        const prepared = this.#tracker.prepareReplace(value);
        this.#tracker.adopt(prepared);
        if (prepared.ops.length > 0)
            this.#publisher.publish(prepared.value, context);
    }

subscribe(listener) {
        return this.#publisher.subscribe(listener);
    }

get value() {
        return this.#publisher.value;
    }

subscribe(listener) {
        return this.#publisher.subscribe(listener);
    }

activate() {
        this.#attachment.activate((frame) => this.#receive(frame));
    }

dispose() {
        if (this.#disposed)
            return;
        this.#disposed = true;
        this.#attachment.dispose();
    }

#receive(frame) {
        if (this.#disposed)
            return;
        try {
            assertCursor(frame.cursor, "frame");
            const expected = this.#cursor + 1;
            if (frame.cursor !== expected) {
                throw new Error(`Replicated state source cursor has a gap: expected ${expected}, received ${frame.cursor}`);
            }
            this.#cursor = frame.cursor;
            this.#publisher.publish(frame.value, frame.context);
        }
        catch (error) {
            this.#fail(toError(error));
        }
    }

#fail(error) {
        if (this.#disposed)
            return;
        this.#disposed = true;
        try {
            this.#attachment.dispose();
        }
        catch (disposeError) {
            this.#report(new AggregateError([error, disposeError], "Replicated state source contract failed"));
            return;
        }
        this.#report(error);
    }

#report(error) {
        try {
            this.#reportError(toError(error));
        }
        catch (reportError) {
            reportErrorAsync(toError(reportError));
        }
    }

function attachReplicatedStateSource(source, options = {}) {
    const attachment = source.attach();
    try {
        const state = new AttachedReplicatedStateImpl(attachment, options);
        state.activate();
        return state;
    }
    catch (error) {
        try {
            attachment.dispose();
        }
        catch (disposeError) {
            throw new AggregateError([error, disposeError], "Failed to attach replicated state source");
        }
        throw error;
    }
}

function assertCursor(cursor, kind) {
    if (!Number.isSafeInteger(cursor))
        throw new TypeError(`Replicated state source ${kind} cursor must be a safe integer`);
}

function isPromiseLike(value) {
    return (((typeof value === "object" && value !== null) || typeof value === "function") &&
        typeof value.then === "function");
}

function reportErrorAsync(error) {
    queueMicrotask(() => {
        throw error;
    });
}

function toError(error) {
    return error instanceof Error ? error : new Error(String(error));
}

export function replicatedState(initialOrSource, options) {
    if (isReplicatedStateSource(initialOrSource))
        return attachReplicatedStateSource(initialOrSource, options);
    return new MutableReplicatedStateImpl(initialOrSource);
}

function isReplicatedStateSource(value) {
    return typeof value.attach === "function";
}

export function acceptWebSockets(server, host, options) {
    server.on("connection", (socket, request) => {
        // Wrap at once so frames sent while authenticating are queued, not lost. Large payloads go out deflated; clients
        // may not send packed frames (a small message could inflate to anything).
        const link = webSocketLink(socket, { compress: true, acceptPacked: false });
        Promise.resolve(options.principal(request)).then((principal) => {
            if (principal === undefined)
                link.close("unauthorized");
            else
                host.accept(link, { ...options, principal, kind: "client" });
        }, () => link.close("authentication failed"));
    });
}

export function toWireError(error) {
    if (error instanceof ChordError) {
        return error.reason === undefined
            ? { code: error.code, message: error.message }
            : { code: error.code, message: error.message, reason: error.reason };
    }
    return { code: "unavailable", message: error instanceof Error ? error.message : String(error) };
}

